INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('d13aeca8-5bb5-5b88-a2ce-1195799ccfb3', 'verbal', 'فهم المقروء', 'mawhiba_l2', 'medium', 'text', '📖 الاختراع
