لماذا كان المخترع يعدّل تصميماً واحداً فقط في كل مرة؟', NULL, '[{"text":"لأنه يخاف من التعب"},{"text":"ليوفر المال"},{"text":"لأنه ينسى الباقي"},{"text":"ليعرف أثر كل تعديل"}]', 3, 'تغيير شيء واحد يكشف أثره بوضوح.', '["mawhiba_l2","mawhiba_l2#16"]', 1, 'mawhiba_l2');
