INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('3d0f9a67-5d1a-5432-a361-9fb28195c1db', 'verbal', 'فهم المقروء', 'mawhiba_l2', 'easy', 'text', '📖 مكتبة الحي
افتتحت بلدية الحي مكتبة صغيرة في حديقة عامة، وفتحت أبوابها من الرابعة عصراً حتى الثامنة مساءً. يستطيع الزائر استعارة كتابين لمدة أسبوعين، ويمكنه تجديد الإعارة مرة واحدة إذا لم يطلب الكتاب شخص آخر. وبعد شهر من الافتتاح ارتفع عدد المستعيرين من أربعين إلى مئة وعشرين، لكن أغلب الكتب المطلوبة كانت كتب القصص، بينما بقيت كتب العلوم على الرفوف.

كم ساعة تبقى المكتبة مفتوحة يومياً؟', NULL, '[{"text":"٤ ساعات"},{"text":"٣ ساعات"},{"text":"٥ ساعات"},{"text":"٨ ساعات"}]', 0, 'من ٤ عصراً إلى ٨ مساءً = ٤ ساعات.', '["mawhiba_l2","mawhiba_l2#19"]', 1, 'mawhiba_l2');
