INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('d40c9d3b-777b-5161-ab00-f444f1dc0e89', 'verbal', 'فهم المقروء', 'mawhiba_l2', 'hard', 'text', '📖 الدراجة والمدينة
قررت مدينة صغيرة تخصيص مسار للدراجات الهوائية في شارعها الرئيسي. بعد ستة أشهر انخفض عدد السيارات في الشارع بنسبة عشرين بالمئة، وقلّ الازدحام صباحاً، لكن أصحاب المحلات اشتكوا من صعوبة وقوف زبائنهم. فاقترح المجلس إنشاء مواقف على الشارع الجانبي.

ما أنسب وصف لحل المجلس؟', NULL, '[{"text":"إلغاء مسار الدراجات"},{"text":"منع السيارات نهائياً"},{"text":"إغلاق الشارع الجانبي"},{"text":"حل يعالج المشكلة الجديدة دون إلغاء المسار"}]', 3, 'الحل: مواقف على الشارع الجانبي، والمسار يبقى.', '["mawhiba_l2","mawhiba_l2#24"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('c03f8299-7155-550e-a246-3e96886c4838', 'flexibility', 'إعادة صياغة', 'mawhiba_l2', 'easy', 'text', 'يريد معلم تعليم مفهوم الكسور بطريقة ممتعة. أي فكرة تقدم المفهوم بأمثلة محسوسة متنوعة؟', NULL, '[{"text":"حفظ القواعد دون أمثلة"},{"text":"مشاهدة الفيديو دون نقاش"},{"text":"تقسيم بيتزا وأشرطة ورق وأكواب ماء"},{"text":"عرض أرقام فقط"}]', 2, 'التنويع في الأمثلة المحسوسة يعزز الفهم.', '["mawhiba_l2","mawhiba_l2#25"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('c24dc69a-3005-5339-ab1d-15a8356ab6d2', 'flexibility', 'تصنيف', 'mawhiba_l2', 'medium', 'text', 'أي الأشياء يمكن تصنيفه مع «أدوات القياس» ومع «أدوات المطبخ» معاً؟', NULL, '[{"text":"مطرقة"},{"text":"كوب مدرّج"},{"text":"مجهر"},{"text":"بوصلة"}]', 1, 'الكوب المدرّج يقيس الحجم ويُستعمل في المطبخ. المطرقة لا تقيس، والمجهر والبوصلة ليسا من أدوات المطبخ.', '["mawhiba_l2","mawhiba_l2#26"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('883163b7-db1a-5017-a2c2-d7d5b8d7da75', 'flexibility', 'تبديل القاعدة', 'mawhiba_l2', 'medium', 'text', 'ما الحد التالي: ١، ٣، ٢، ٦، ٣، ٩، ٤، ؟', NULL, '[{"text":"٨"},{"text":"١٠"},{"text":"١٦"},{"text":"١٢"}]', 3, 'المتتالية تتناوب: الحدود الفردية ١، ٢، ٣، ٤ والزوجية ٣، ٦، ٩، ١٢. بعد ٤ يأتي ٤ × ٣ = ١٢.', '["mawhiba_l2","mawhiba_l2#27"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('4cd784d7-620f-51e1-a1e6-12ffb82d764d', 'flexibility', 'إعادة صياغة', 'mawhiba_l2', 'medium', 'text', 'أي طريقة تساعد على تذكر قائمة مشتريات طويلة بسرعة؟', NULL, '[{"text":"قراءتها مرة واحدة بصمت"},{"text":"ربط كل عنصر بصورة ذهنية مميزة في مكان مألوف"},{"text":"تجاهلها"},{"text":"عدّها عدّاً فقط"}]', 1, 'الربط بصور ومكان مألوف طريقة معروفة لتقوية الذاكرة.', '["mawhiba_l2","mawhiba_l2#28"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('ba4d47b7-5dae-5564-a8ee-d628b21c9a6a', 'flexibility', 'حل مشكلات', 'mawhiba_l2', 'medium', 'text', 'أراد أحمد أن يعبر نهراً بقارب يحمل شخصاً واحداً فقط ومعه ذئب وخروف وعشب. أول خطوة آمنة هي أن:', NULL, '[{"text":"ينقل الخروف أولاً"},{"text":"ينقل الذئب أولاً"},{"text":"ينقل العشب أولاً"},{"text":"ينقل الذئب والخروف معاً"}]', 0, 'لو ترك الذئب مع الخروف أكله، ولو ترك الخروف مع العشب أكله. نقل الخروف أولاً يترك الذئب والعشب وهما آمنان.', '["mawhiba_l2","mawhiba_l2#29"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('f9f2d56b-f7dd-59d0-a775-ee5e89cdabf7', 'flexibility', 'إعادة صياغة', 'mawhiba_l2', 'easy', 'text', 'إذا فشلت طريقة في حل مسألة ثلاث مرات متتالية، فما الخطوة الأذكى؟', NULL, '[{"text":"تكرار الطريقة نفسها بسرعة أكبر"},{"text":"إعادة النظر في الفرضية وتجريب طريقة مختلفة"},{"text":"ترك المسألة نهائياً"},{"text":"تغيير السؤال"}]', 1, 'المرونة تعني تغيير المقاربة عند فشلها.', '["mawhiba_l2","mawhiba_l2#30"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('34dbbb85-d3f2-5aea-aabb-66e400218b37', 'flexibility', 'إعادة صياغة', 'mawhiba_l2', 'hard', 'text', 'كيف يمكن لقطعة ورق واحدة أن تحمل وزناً أكبر؟', NULL, '[{"text":"ببلّها بالماء"},{"text":"بتمزيقها قطعاً"},{"text":"بطيّها على شكل أسطوانة أو طيات"},{"text":"بفردها على الأرض"}]', 2, 'الطي أو الأسطوانة يوزّع الحمل ويزيد المتانة.', '["mawhiba_l2","mawhiba_l2#31"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('1177c0ea-dfb1-5539-a75b-f92f15e6d4bd', 'flexibility', 'حل مشكلات', 'mawhiba_l2', 'easy', 'text', 'تريد وزن ١٢ كغ باستخدام ميزان ذي كفتين وأوزان ٥ كغ و٣ كغ و٤ كغ فقط. أي وضع يصح؟', NULL, '[{"text":"٥ + ٣ في كفة و٤ في الأخرى"},{"text":"٥ + ٥ في كفة"},{"text":"٣ + ٣ + ٣ في كفة و٣ في الأخرى"},{"text":"٥ + ٣ + ٤ في كفة واحدة"}]', 3, '٥ + ٣ + ٤ = ١٢.', '["mawhiba_l2","mawhiba_l2#32"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('f4fde945-7b33-55eb-a473-e0797764a570', 'flexibility', 'إعادة صياغة', 'mawhiba_l2', 'medium', 'text', 'أي الأفكار التالية يمكنه أن يقلل ضياع الماء من خزان مكشوف دون استعمال كهرباء؟', NULL, '[{"text":"تغطيته بغطاء عائم"},{"text":"إضاءته ليلاً"},{"text":"تحريك الماء بمضخة"},{"text":"تلوين جدرانه"}]', 0, 'الغطاء يقلل التبخر.', '["mawhiba_l2","mawhiba_l2#33"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('e1709049-cea6-55a7-a58c-72b81df240a5', 'flexibility', 'أفكار', 'mawhiba_l2', 'hard', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: الملعقة.', NULL, '[{"text":"تحريك الشاي"},{"text":"خلط السكر في الكوب"},{"text":"النظر إلى انعكاس الوجه على سطحها المصقول"},{"text":"تقليب الحساء"}]', 2, 'الثلاثة للتحريك، والمختلف يعتمد على الانعكاس.', '["mawhiba_l2","mawhiba_l2#34"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('8065b0f8-49d5-53d5-a708-9a1a534b82d3', 'flexibility', 'تبديل القاعدة', 'mawhiba_l2', 'hard', 'text', 'ما الحد التالي: ١٠، ٥، ٨، ٤، ٦، ٣، ٤، ؟', NULL, '[{"text":"١"},{"text":"٢"},{"text":"٣"},{"text":"٥"}]', 1, 'التتابع فردياً: ١٠، ٨، ٦، ٤ ينقص ٢، وزوجياً ٥، ٤، ٣، ٢ ينقص ١. الحد التالي ٢.', '["mawhiba_l2","mawhiba_l2#35"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('275c10cb-abf7-5ce4-a1df-cfc4dbf1a35c', 'flexibility', 'أفكار', 'mawhiba_l2', 'medium', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: المظلة.', NULL, '[{"text":"وقاية من المطر"},{"text":"وقاية من الثلج الخفيف"},{"text":"وقاية من الشمس"},{"text":"وقاية من الرذاذ"}]', 2, 'الاستخدامات الأخرى للوقاية من الماء المتساقط، والمختلف الوقاية من الشمس.', '["mawhiba_l2","mawhiba_l2#36"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('10746868-dd4d-55fa-ab21-017c656f4cd8', 'flexibility', 'حل مشكلات', 'mawhiba_l2', 'easy', 'text', 'تريد عبور شارع مزدحم ليس فيه إشارة. أي خطوة هي الأكثر أماناً أولاً؟', NULL, '[{"text":"الركض فوراً"},{"text":"العبور مع إغماض العينين"},{"text":"اللحاق بأول سيارة تمر"},{"text":"النظر يميناً ويساراً والانتظار حتى يخلو الطريق"}]', 3, 'الأمان يبدأ بملاحظة حركة السيارات والانتظار قبل العبور.', '["mawhiba_l2","mawhiba_l2#37"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('52d31504-bd35-5958-abf2-61e32ef4dfab', 'flexibility', 'تبديل القاعدة', 'mawhiba_l2', 'hard', 'text', 'ما الحد التالي: أ، ج، ب، د، ج، هـ، د، ؟', NULL, '[{"text":"و"},{"text":"ز"},{"text":"ح"},{"text":"هـ"}]', 0, 'نبدل: +٢ حرفاً ثم −١ حرفاً. بعد د (+٢) نصل إلى و.', '["mawhiba_l2","mawhiba_l2#38"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('c6a6e3d8-8180-5362-a5ab-a6955e793613', 'flexibility', 'تبديل القاعدة', 'mawhiba_l2', 'medium', 'text', 'ما الحد المفقود: ٢، ٣، ٦، ٧، ١٤، ١٥، ؟', NULL, '[{"text":"٢٨"},{"text":"٢٩"},{"text":"٣٠"},{"text":"١٦"}]', 2, 'نبدل: +١ ثم ×٢. بعد ١٥ نضرب ×٢ فنحصل على ٣٠.', '["mawhiba_l2","mawhiba_l2#39"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('2b819b6e-2852-5033-add8-e35e1373e700', 'flexibility', 'إعادة صياغة', 'mawhiba_l2', 'medium', 'text', 'أي مجموعة أفكار تُظهر مرونة أكبر في استعمال كيس قماشي؟', NULL, '[{"text":"حمل التسوق، وسادة، علم، قطعة تنظيف"},{"text":"حمل التسوق، حمل الكتب، حمل الخضار، حمل الفاكهة"},{"text":"حقيبة، حقيبة صغيرة، حقيبة كبيرة، حقيبة ظهر"},{"text":"كيس للقمامة فقط"}]', 0, 'الاستخدامات متنوعة الفئة لا تدور حول فكرة الحمل وحدها.', '["mawhiba_l2","mawhiba_l2#40"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a4234a47-1b39-5c2b-aa00-4ad0579aa611', 'flexibility', 'أفكار', 'mawhiba_l2', 'medium', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: الحبل.', NULL, '[{"text":"ربط صندوق"},{"text":"تثبيت خيمة"},{"text":"قياس طول بوضعه بجانب شيء"},{"text":"شد غصن شجرة"}]', 2, 'الأفكار الثلاث الأخرى تعتمد على الربط والشد والتثبيت، والاستخدام المختلف هو القياس.', '["mawhiba_l2","mawhiba_l2#41"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('14d9c862-4755-57b6-ab67-261805722640', 'flexibility', 'أفكار', 'mawhiba_l2', 'easy', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: المسطرة.', NULL, '[{"text":"قياس الطول"},{"text":"رسم خط مستقيم"},{"text":"قياس عرض الكتاب"},{"text":"قياس سمك الدفتر"}]', 1, 'الثلاثة قياس، والمختلف الرسم.', '["mawhiba_l2","mawhiba_l2#42"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a1084c3c-08c1-5089-ae11-ca6e33734609', 'flexibility', 'تصنيف', 'mawhiba_l2', 'easy', 'text', '«زجاجة، قارورة، كأس، كوب» تجتمع في أنها كلها:', NULL, '[{"text":"أدوات للكتابة"},{"text":"وسائل نقل"},{"text":"أوانٍ للسوائل"},{"text":"أجهزة كهربائية"}]', 2, 'كلها تُستخدم لحفظ السوائل أو شربها.', '["mawhiba_l2","mawhiba_l2#43"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('b3b32a6d-729c-5e46-aa11-d9f41f0fcb83', 'flexibility', 'أفكار', 'mawhiba_l2', 'hard', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: كرة التنس.', NULL, '[{"text":"رمي للعب"},{"text":"كتم صوت الاحتكاك بوضعها تحت أرجل الكرسي"},{"text":"ارتداد على الجدار"},{"text":"تمرير بين اللاعبين"}]', 1, 'الثلاثة تعتمد على الرمي والارتداد، والمختلف يستفيد من مرونتها لتقليل الصوت.', '["mawhiba_l2","mawhiba_l2#44"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('9a5f9df7-9d71-5f9a-afa8-754f9f741ff2', 'flexibility', 'تصنيف', 'mawhiba_l2', 'easy', 'text', 'المطلوب: مجموعة تضم «جبل، وادي، تل، سهل». ما الصفة الجامعة؟', NULL, '[{"text":"كائنات حية"},{"text":"مواد صلبة فقط"},{"text":"تضاريس طبيعية"},{"text":"مدن"}]', 2, 'كلها أشكال لسطح الأرض.', '["mawhiba_l2","mawhiba_l2#45"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('c523332c-297b-528f-aa94-d9e4bd68399e', 'flexibility', 'تبديل القاعدة', 'mawhiba_l2', 'medium', 'text', 'ما الحد التالي: ٧، ٩، ٨، ١٠، ٩، ١١، ؟', NULL, '[{"text":"١٢"},{"text":"٩"},{"text":"١١"},{"text":"١٠"}]', 3, 'نبدل: +٢ ثم −١. ١١ − ١ = ١٠.', '["mawhiba_l2","mawhiba_l2#46"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('ce481d97-dfe4-5c38-a7bd-ba98c6536885', 'flexibility', 'أفكار', 'mawhiba_l2', 'medium', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: المنشفة.', NULL, '[{"text":"سدّ فتحة أسفل الباب لمنع تيار الهواء"},{"text":"تجفيف الجسم"},{"text":"مسح اليدين"},{"text":"تجفيف الأطباق"}]', 0, 'الثلاثة للتجفيف، والمختلف للسدّ.', '["mawhiba_l2","mawhiba_l2#47"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('8dd8d23f-1366-5595-a3c4-0f3d353265f1', 'flexibility', 'تصنيف', 'mawhiba_l2', 'easy', 'text', 'الصندوق ١: (قلم، مسطرة، ممحاة). الصندوق ٢: (كوب، صحن، ملعقة). أي الأشياء يصح وضعه في الصندوق ١؟', NULL, '[{"text":"شوكة"},{"text":"فنجان"},{"text":"سكين"},{"text":"مبراة"}]', 3, 'الصندوق ١ أدوات مكتبية، والمبراة منها.', '["mawhiba_l2","mawhiba_l2#48"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('b1a4947d-0ca4-5dae-ac6f-e1cb728bca18', 'quantitative', 'جبر', 'mawhiba_l2', 'medium', 'text', 'اشترى خالد ٣ دفاتر وقلمين بمبلغ ٢٩ ريالاً. إذا كان سعر القلم ٤ ريالات، فكم سعر الدفتر؟', NULL, '[{"text":"٨"},{"text":"٧"},{"text":"١٠"},{"text":"٥"}]', 1, 'ثمن القلمين ٨، فثمن الدفاتر ٢١، وسعر الدفتر ٢١ ÷ ٣ = ٧ ريالات.', '["mawhiba_l2","mawhiba_l2#49"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('345a8edc-681b-5ec8-ac33-bf84c3830ff3', 'quantitative', 'تناسب', 'mawhiba_l2', 'medium', 'text', 'يحتاج ٣ عمال إلى ١٢ يوماً لإنجاز مشروع. كم يوماً يحتاج ٦ عمال بنفس معدل العمل؟', NULL, '[{"text":"٢٤"},{"text":"٤"},{"text":"٦"},{"text":"٩"}]', 2, 'كمية العمل = ٣ × ١٢ = ٣٦ عامل-يوم، و٣٦ ÷ ٦ = ٦ أيام.', '["mawhiba_l2","mawhiba_l2#50"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('dadd4aa5-f870-5a12-a3c1-a1048fb7c7f6', 'quantitative', 'متتاليات', 'mawhiba_l2', 'easy', 'text', 'ما العدد التالي: ١، ٤، ٩، ١٦، ٢٥، ؟', NULL, '[{"text":"٣٦"},{"text":"٣٠"},{"text":"٣٥"},{"text":"٤٩"}]', 0, 'مربعات الأعداد ١ إلى ٥، والتالي ٣٦ = ٦².', '["mawhiba_l2","mawhiba_l2#51"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('69f5287e-cf29-5a4b-a2ff-be9a8a716f96', 'quantitative', 'جبر', 'mawhiba_l2', 'medium', 'text', 'عددان مجموعهما ٤٨ والفرق بينهما ١٢. ما العدد الأكبر؟', NULL, '[{"text":"٣٦"},{"text":"٢٤"},{"text":"١٨"},{"text":"٣٠"}]', 3, 'الأكبر = (٤٨ + ١٢) ÷ ٢ = ٣٠، والأصغر ١٨.', '["mawhiba_l2","mawhiba_l2#52"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('3addb1ee-5a4c-535b-a71b-0a14687261b0', 'spatial', 'تدوير', 'mawhiba_l2', 'medium', 'image', 'يوضح الشكل في الأعلى نمطاً من المربعات الملونة. أي الأشكال المرقمة يمثل النمط بعد تدويره ٩٠° باتجاه عقارب الساعة؟', '/assets/bunyan/mawhiba2/a-r5.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 2, 'عند تدوير الشبكة ٩٠° باتجاه عقارب الساعة ينتقل كل مربع ملوّن إلى موضعه الجديد، والشكل رقم ٣ هو الناتج. الأشكال الأخرى تمثل تدويرات أخرى أو انعكاساً.', '["mawhiba_l2","mawhiba_l2#53"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('95d67f55-7ecd-5c9c-a0ab-41473322fc4e', 'spatial', 'تدوير', 'mawhiba_l2', 'medium', 'image', 'يوضح الشكل في الأعلى نمطاً من المربعات الملونة. أي الأشكال المرقمة يمثل النمط بعد تدويره ١٨٠°؟', '/assets/bunyan/mawhiba2/a-r6.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 0, 'عند تدوير الشبكة ١٨٠° ينتقل كل مربع ملوّن إلى موضعه الجديد، والشكل رقم ١ هو الناتج. الأشكال الأخرى تمثل تدويرات أخرى أو انعكاساً.', '["mawhiba_l2","mawhiba_l2#54"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('4b5a8503-aad8-52cf-a319-caeab505ad08', 'spatial', 'تدوير', 'mawhiba_l2', 'medium', 'image', 'يوضح الشكل في الأعلى نمطاً من المربعات الملونة. أي الأشكال المرقمة يمثل النمط بعد تدويره ٩٠° عكس عقارب الساعة؟', '/assets/bunyan/mawhiba2/a-r7.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 3, 'عند تدوير الشبكة ٩٠° عكس عقارب الساعة ينتقل كل مربع ملوّن إلى موضعه الجديد، والشكل رقم ٤ هو الناتج. الأشكال الأخرى تمثل تدويرات أخرى أو انعكاساً.', '["mawhiba_l2","mawhiba_l2#55"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('aafb7189-68a3-51cc-a3e6-e79bd0704fba', 'spatial', 'مصفوفة', 'mawhiba_l2', 'medium', 'image', 'في المصفوفة الظاهرة في الصورة قاعدة تحكم الصفوف والأعمدة. أي الأشكال المرقمة يكمل الخلية الناقصة (؟)؟', '/assets/bunyan/mawhiba2/a-r8.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 2, 'في كل صف يزيد العدد واحداً من خلية إلى التي تليها، وفي كل عمود أيضاً يزيد واحداً. الخلية الناقصة ٣ + ٢ = ٥ دوائر. الإجابة هي الشكل رقم ٣.', '["mawhiba_l2","mawhiba_l2#56"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('dd092f56-ea98-5dcc-a2e4-7dbb8ac0e9a6', 'quantitative', 'عد', 'mawhiba_l2', 'hard', 'text', 'إذا صافح كل شخص من ٥ أشخاص كل شخص آخر مرة واحدة، فكم عدد المصافحات؟', NULL, '[{"text":"٢٠"},{"text":"١٠"},{"text":"٢٥"},{"text":"١٥"}]', 1, '٥ × ٤ ÷ ٢ = ١٠ مصافحات.', '["mawhiba_l2","mawhiba_l2#57"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('05d61e53-757c-5e26-a352-4c9e60ace19a', 'quantitative', 'أعداد', 'mawhiba_l2', 'medium', 'text', 'ما أصغر عدد صحيح موجب يقبل القسمة على ٤ و٦ و٨ معاً؟', NULL, '[{"text":"٢٤"},{"text":"١٢"},{"text":"٤٨"},{"text":"٣٢"}]', 0, 'المضاعف المشترك الأصغر لـ ٤ و٦ و٨ هو ٢٤.', '["mawhiba_l2","mawhiba_l2#58"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('1ce8525e-5e40-59ac-a99e-61bd957cfa09', 'quantitative', 'جبر', 'mawhiba_l2', 'medium', 'text', 'في فصل ٣٠ طالباً، عدد البنات يزيد على عدد الأولاد بـ ٦. كم عدد البنات؟', NULL, '[{"text":"٢٤"},{"text":"١٢"},{"text":"١٥"},{"text":"١٨"}]', 3, 'ب + و = ٣٠ و ب − و = ٦ فب = ١٨.', '["mawhiba_l2","mawhiba_l2#59"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a99e1460-8dee-525f-a95e-02b7a6aed02d', 'quantitative', 'كسور', 'mawhiba_l2', 'easy', 'text', 'يملأ صنبور ثلث خزان في ٦ دقائق. كم دقيقة يحتاج لملء الخزان كله؟', NULL, '[{"text":"١٢"},{"text":"٩"},{"text":"٢٤"},{"text":"١٨"}]', 3, 'ثلث الخزان = ٦ دقائق، فالخزان كله = ٦ × ٣ = ١٨ دقيقة.', '["mawhiba_l2","mawhiba_l2#60"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('5b27f8e9-d6eb-570e-ab2d-7c968bae8c95', 'spatial', 'مكعبات', 'mawhiba_l2', 'medium', 'image', 'يبيّن الشكل المنظر العلوي لمكعبات متطابقة مرصوصة، والرقم هو عدد المكعبات في العمود. ما أكبر ارتفاع للمجسم مقاساً بعدد المكعبات؟', '/assets/bunyan/mawhiba2/a-r13.png', '[{"text":"٤"},{"text":"٢"},{"text":"٣"},{"text":"٧"}]', 2, 'أكبر رقم في الشكل هو ٣، فهذا هو أكبر ارتفاع.', '["mawhiba_l2","mawhiba_l2#61"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('2255cc25-d534-521f-ad63-7954e7c93627', 'quantitative', 'تناسب', 'mawhiba_l2', 'medium', 'text', 'ملأ عامل خزاناً بمعدل ٢٠ لتراً في الدقيقة بينما يتسرب ٥ لترات في الدقيقة. كم دقيقة يلزم لملء ٤٥٠ لتراً؟', NULL, '[{"text":"٢٢٫٥"},{"text":"٣٠"},{"text":"١٨"},{"text":"٢٥"}]', 1, 'الصافي = ١٥ لتراً/دقيقة، و٤٥٠ ÷ ١٥ = ٣٠ دقيقة.', '["mawhiba_l2","mawhiba_l2#62"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('c870ee10-60f9-5373-a1ae-92566748793e', 'quantitative', 'نسب', 'mawhiba_l2', 'hard', 'text', 'ارتفع سعر سلعة ١٠٪ ثم انخفض ١٠٪. إذا كان السعر الأصلي ١٠٠ ريال، فما السعر بعد التغييرين بالريال؟', NULL, '[{"text":"٩٩"},{"text":"١٠٠"},{"text":"١٠١"},{"text":"٩٨"}]', 0, '١٠٠ × ١٫١ = ١١٠، ثم ١١٠ × ٠٫٩ = ٩٩. الزيادة والنقص بالنسبة نفسها لا يعيدان السعر الأصلي.', '["mawhiba_l2","mawhiba_l2#63"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('50bd5a89-afd4-5e50-a79c-ebb29dc2abd4', 'quantitative', 'نسب', 'mawhiba_l2', 'medium', 'text', 'زاد عدد طلاب مدرسة من ٤٠٠ إلى ٥٢٠. ما نسبة الزيادة؟', NULL, '[{"text":"٢٠٪"},{"text":"٢٣٪"},{"text":"١٢٠٪"},{"text":"٣٠٪"}]', 3, 'الزيادة = ١٢٠، ونسبتها ١٢٠ ÷ ٤٠٠ = ٣٠٪.', '["mawhiba_l2","mawhiba_l2#64"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('1c0b1ba9-2aa9-5b5b-a5be-e50cac97c808', 'quantitative', 'كسور', 'mawhiba_l2', 'medium', 'text', 'ما ناتج ١/٢ + ١/٣ + ١/٦؟', NULL, '[{"text":"١"},{"text":"٥/٦"},{"text":"٣/٤"},{"text":"١١/١٢"}]', 0, 'بتوحيد المقام ٦: ٣/٦ + ٢/٦ + ١/٦ = ٦/٦ = ١.', '["mawhiba_l2","mawhiba_l2#65"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('24d9f6e3-8224-5cd6-a489-9b626dd07fd2', 'quantitative', 'متتاليات', 'mawhiba_l2', 'medium', 'text', 'ما العدد المفقود: ٢، ٤، ٧، ١١، ؟، ٢٢', NULL, '[{"text":"١٥"},{"text":"١٧"},{"text":"١٨"},{"text":"١٦"}]', 3, 'الفروق ٢، ٣، ٤، ٥، ٦: ١١ + ٥ = ١٦ ثم ١٦ + ٦ = ٢٢.', '["mawhiba_l2","mawhiba_l2#66"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('b240b608-adfe-567e-ad75-624dcaaaa4ec', 'spatial', 'مصفوفة', 'mawhiba_l2', 'medium', 'image', 'في المصفوفة الظاهرة في الصورة قاعدة تحكم الصفوف والأعمدة. أي الأشكال المرقمة يكمل الخلية الناقصة (؟)؟', '/assets/bunyan/mawhiba2/a-r19.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 0, 'كل خلية تدور ٩٠° عن التي قبلها في الصف والعمود. الخلية الناقصة ٢٧٠ + ٩٠ = ٣٦٠ أي ٠° (المثلث بالاتجاه الأصلي). الإجابة هي الشكل رقم ١.', '["mawhiba_l2","mawhiba_l2#67"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('c50be221-a53d-531e-a67b-93b41ee3c721', 'quantitative', 'متتاليات', 'mawhiba_l2', 'hard', 'text', 'ما العدد التالي: ٥، ١٠، ٩، ١٨، ١٧، ؟', NULL, '[{"text":"١٦"},{"text":"٢٧"},{"text":"٣٤"},{"text":"٣٥"}]', 2, 'القاعدة بالتناوب: ضرب في ٢ ثم طرح ١. بعد ١٧ ضرب في ٢ = ٣٤.', '["mawhiba_l2","mawhiba_l2#68"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('d57e4855-19a4-58e7-ae8c-dda8cdbcb963', 'spatial', 'مصفوفة', 'mawhiba_l2', 'medium', 'image', 'في المصفوفة الظاهرة في الصورة قاعدة تحكم الصفوف والأعمدة. أي الأشكال المرقمة يكمل الخلية الناقصة (؟)؟', '/assets/bunyan/mawhiba2/a-r21.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 3, 'في كل صف الخلية الثالثة = الأولى − الثانية: ٣ − ٢ = ١. الإجابة هي الشكل رقم ٤.', '["mawhiba_l2","mawhiba_l2#69"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('b68c7094-42a6-550e-afe3-db189eee43f0', 'quantitative', 'زمن', 'mawhiba_l2', 'medium', 'text', 'رحلة بدأت ٩:٤٥ صباحاً وانتهت ٣:١٠ عصراً. كم دقيقة استغرقت؟', NULL, '[{"text":"٣٠٥"},{"text":"٣٢٥"},{"text":"٣٣٥"},{"text":"٣٨٥"}]', 1, 'من ٩:٤٥ إلى ٣:١٠ مساءً (١٠:١٥) = ٥ ساعات و٢٥ دقيقة = ٣٢٥ دقيقة.', '["mawhiba_l2","mawhiba_l2#70"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a8254ef7-cbb8-5161-a7cb-1395e07f4506', 'spatial', 'مكعبات', 'mawhiba_l2', 'medium', 'image', 'يبيّن الشكل المنظر العلوي لمجموعة من مكعبات متطابقة مرصوصة فوق بعضها، والرقم في كل مربع هو عدد المكعبات في ذلك العمود. كم عدد المكعبات الكلي؟', '/assets/bunyan/mawhiba2/a-r23.png', '[{"text":"١٥"},{"text":"١٧"},{"text":"١٤"},{"text":"٢٠"}]', 0, 'نجمع الأرقام في كل المربعات: ٢ + ٢ + ١ + ٠ + ٣ + ١ + ١ + ١ + ٤ = ١٥ مكعباً.', '["mawhiba_l2","mawhiba_l2#71"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a7ca7dc9-3989-55fa-a8e0-8e0b2dfc7f95', 'spatial', 'انعكاس', 'mawhiba_l2', 'medium', 'image', 'يوضع مرآة عمودية على الحافة اليمنى للشكل الظاهر في الأعلى. أي الأشكال المرقمة يمثل انعكاسه في المرآة؟', '/assets/bunyan/mawhiba2/a-r24.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 2, 'الانعكاس في مرآة عمودية يقلب الشكل يميناً ويساراً مع بقاء الأعلى والأسفل في مكانهما، والناتج هو الشكل رقم ٣.', '["mawhiba_l2","mawhiba_l2#72"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('864fddef-f416-5bcb-a320-7477b1ab5e95', 'scientific', 'منهج', 'mawhiba_l2', 'medium', 'text', 'أراد طالب معرفة أثر كمية الضوء في نمو نبتة. أي متغير يجب أن يبقى ثابتاً؟', NULL, '[{"text":"كمية الضوء"},{"text":"كمية الماء ونوع التربة"},{"text":"طول النبتة النهائي"},{"text":"عدد الأيام فقط"}]', 1, 'عند اختبار متغير واحد تُثبّت باقي العوامل.', '["mawhiba_l2","mawhiba_l2#73"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('22ffa273-5167-5887-a780-f1a32ebfe08c', 'scientific', 'صوت', 'mawhiba_l2', 'easy', 'text', 'لماذا نرى البرق قبل أن نسمع الرعد؟', NULL, '[{"text":"لأن سرعة الضوء أكبر كثيراً من سرعة الصوت"},{"text":"لأن الرعد يحدث بعد البرق بساعة"},{"text":"لأن الصوت لا ينتقل في الهواء"},{"text":"لأن العين أسرع من الأذن"}]', 0, 'الضوء أسرع بكثير من الصوت، فيصل أولاً.', '["mawhiba_l2","mawhiba_l2#74"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('70e4829d-ec2a-56b9-a5d9-a494430fb6de', 'scientific', 'قوى', 'mawhiba_l2', 'medium', 'text', 'يقف طالب على الأرض. أي قوتين متوازنتان؟', NULL, '[{"text":"وزنه وسرعته"},{"text":"كتلته وطوله"},{"text":"وزنه وردّ فعل الأرض عليه"},{"text":"احتكاكه وحرارته"}]', 2, 'الوزن لأسفل وردّ فعل السطح لأعلى فيتزن الجسم.', '["mawhiba_l2","mawhiba_l2#75"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a61e442c-96c9-5271-a5eb-636626552e5a', 'scientific', 'منهج', 'mawhiba_l2', 'hard', 'text', 'يقول طالب: «الخبز يتعفن أسرع في المكان الدافئ الرطب». أي تجربة تختبر العبارة جيداً؟', NULL, '[{"text":"قطعة واحدة في مكان دافئ فقط"},{"text":"ثلاث قطع مختلفة الأنواع في أماكن مختلفة"},{"text":"قطعة في الظلام وأخرى بجانب النافذة"},{"text":"قطعتان متماثلتان، إحداهما في مكان دافئ رطب والأخرى في بارد جاف"}]', 3, 'نغيّر الظروف فقط ونثبت نوع الخبز وحجمه.', '["mawhiba_l2","mawhiba_l2#76"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('ba36d323-27a2-5747-aa6d-24495843de9c', 'scientific', 'أرض', 'mawhiba_l2', 'medium', 'text', 'عند خسوف القمر يكون ترتيب الأجرام:', NULL, '[{"text":"الشمس ثم القمر ثم الأرض"},{"text":"الشمس ثم الأرض ثم القمر"},{"text":"القمر ثم الشمس ثم الأرض"},{"text":"الأرض ثم الشمس ثم القمر"}]', 1, 'الأرض تحجب ضوء الشمس عن القمر.', '["mawhiba_l2","mawhiba_l2#77"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('855d0939-0e65-537d-ace3-450082c4fb80', 'scientific', 'منهج', 'mawhiba_l2', 'medium', 'text', 'في تجربة عن أثر السماد، المتغير المستقل هو:', NULL, '[{"text":"طول النبات"},{"text":"لون الورق"},{"text":"كمية السماد"},{"text":"وقت القياس"}]', 2, 'المتغير المستقل هو ما يغيّره الباحث عمداً.', '["mawhiba_l2","mawhiba_l2#78"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('3ff7bc92-d2e7-550a-aab4-45c47ee51063', 'scientific', 'طاقة', 'mawhiba_l2', 'easy', 'text', 'أي تحول طاقة يحدث في مصباح كهربائي متوهج؟', NULL, '[{"text":"كهربائية إلى ضوئية وحرارية"},{"text":"حركية إلى كيميائية"},{"text":"ضوئية إلى كهربائية"},{"text":"صوتية إلى حرارية"}]', 0, 'المصباح يحول الطاقة الكهربائية إلى ضوء وحرارة.', '["mawhiba_l2","mawhiba_l2#79"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('cffe5251-375e-5f52-a36f-0d52f87809dc', 'scientific', 'رافعة', 'mawhiba_l2', 'medium', 'image', 'رافعة (لوح) محمولة على نقطة ارتكاز في المنتصف المعلّم. على اليسار ثقل ٢٠ نيوتن على بعد ٣ أمتار. ما الثقل المجهول على اليمين على بعد ٢ متر ليتزن اللوح أفقياً؟ (أهمل وزن اللوح)', '/assets/bunyan/mawhiba2/a-s8.png', '[{"text":"٢٠ نيوتن"},{"text":"١٣٫٣ نيوتن"},{"text":"٣٠ نيوتن"},{"text":"٤٠ نيوتن"}]', 2, 'شرط الاتزان: الثقل × البعد متساوٍ على الجهتين: ٢٠ × ٣ = ٦٠، فالثقل المجهول × ٢ = ٦٠، أي ٣٠ نيوتن.', '["mawhiba_l2","mawhiba_l2#80"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('e05c5a0e-8625-5900-a2cb-a73f9bc21250', 'scientific', 'ضوء', 'mawhiba_l2', 'easy', 'text', 'تتكون الظلال لأن الضوء:', NULL, '[{"text":"ينتقل في دوائر"},{"text":"ينتقل في خطوط مستقيمة"},{"text":"يحتاج وسطاً مادياً"},{"text":"يتحول إلى صوت"}]', 1, 'الضوء ينتقل في خط مستقيم فلا يصل خلف الجسم المعتم.', '["mawhiba_l2","mawhiba_l2#81"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('7b5d734b-7264-5552-a59a-ecf16a4e65f1', 'scientific', 'بكرات', 'mawhiba_l2', 'easy', 'image', 'تُستخدم بكرة ثابتة واحدة لرفع ثقل ٥٠ نيوتن كما في الشكل. ما أقل قوة شدّ تقريباً (بإهمال الاحتكاك ووزن الحبل)؟', '/assets/bunyan/mawhiba2/a-s10.png', '[{"text":"٥٠ نيوتن"},{"text":"٢٥ نيوتن"},{"text":"١٠٠ نيوتن"},{"text":"٥ نيوتن"}]', 0, 'البكرة الثابتة تغيّر اتجاه القوة فقط ولا تقلّلها، فقوة الشدّ تساوي الثقل: ٥٠ نيوتن.', '["mawhiba_l2","mawhiba_l2#82"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('d26b52a4-9165-5745-a906-a565977f8f8a', 'scientific', 'أرض', 'mawhiba_l2', 'medium', 'text', 'أي الصخور تتكون من تبريد الصهارة؟', NULL, '[{"text":"الرسوبية"},{"text":"المتحولة"},{"text":"الصخور النارية"},{"text":"الجيرية فقط"}]', 2, 'الصخور النارية تتكون من تجمد الصهارة أو اللابة.', '["mawhiba_l2","mawhiba_l2#83"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('d8522656-33af-58d1-aa5a-993613da0f36', 'scientific', 'أرض', 'mawhiba_l2', 'easy', 'text', 'ما سبب تعاقب الليل والنهار؟', NULL, '[{"text":"دوران الأرض حول محورها"},{"text":"دوران الأرض حول الشمس"},{"text":"ميل القمر"},{"text":"بعد الأرض عن الشمس"}]', 0, 'دوران الأرض حول نفسها ينقل المناطق بين الضوء والظلام.', '["mawhiba_l2","mawhiba_l2#84"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a776d70f-2ef4-58fb-a8be-e90fc8adbf0c', 'scientific', 'قوى', 'mawhiba_l2', 'medium', 'text', 'سيارة كتلتها ١٠٠٠ كغ وأخرى ٢٠٠٠ كغ تتحركان بنفس السرعة. أيهما أصعب إيقافاً بنفس القوة؟', NULL, '[{"text":"الصغيرة لأن كتلتها أقل"},{"text":"الكبيرة، لأن كتلتها أكبر"},{"text":"متساويتان دائماً"},{"text":"لا علاقة للكتلة"}]', 1, 'الكتلة الأكبر تعني قصوراً ذاتياً أكبر وزخماً أكبر، فتحتاج قوة أكبر أو زمناً أطول للإيقاف.', '["mawhiba_l2","mawhiba_l2#85"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('043571ae-2d38-5249-adeb-38f08d80d84c', 'scientific', 'كهرباء', 'mawhiba_l2', 'hard', 'text', 'أُضيف مصباح ثانٍ على التوالي في دائرة بسيطة ببطارية واحدة. ماذا يحدث غالباً لإضاءة كل مصباح؟', NULL, '[{"text":"تزداد"},{"text":"لا تتغير تماماً"},{"text":"ينطفئ الاثنان دائماً"},{"text":"تقل"}]', 3, 'المقاومة الكلية تزيد في التوالي فيقل التيار وتضعف الإضاءة.', '["mawhiba_l2","mawhiba_l2#86"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('35438b1f-55dd-5a27-a472-b42c440616bb', 'scientific', 'قوى', 'mawhiba_l2', 'hard', 'text', 'سقط حجر وريشة داخل أنبوب مفرغ من الهواء. ماذا يحدث؟', NULL, '[{"text":"يصلان القاع معاً تقريباً"},{"text":"يصل الحجر أولاً بوضوح"},{"text":"تصل الريشة أولاً"},{"text":"لا يسقط أي منهما"}]', 0, 'في الفراغ لا توجد مقاومة هواء، فتتساوى عجلة سقوط الجسمين.', '["mawhiba_l2","mawhiba_l2#87"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('48ed31bb-eb6f-588f-a5d9-e6bc5685732a', 'scientific', 'صوت', 'mawhiba_l2', 'easy', 'text', 'الصوت لا ينتقل في:', NULL, '[{"text":"الماء"},{"text":"الهواء"},{"text":"الحديد"},{"text":"الفراغ"}]', 3, 'الصوت يحتاج وسطاً مادياً لينتقل.', '["mawhiba_l2","mawhiba_l2#88"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('5a3177c8-baf7-547d-aa36-a31f1f1d1a6b', 'scientific', 'تروس', 'mawhiba_l2', 'easy', 'image', 'خمسة تروس متعشقة في صف، والترس ١ يدور باتجاه عقارب الساعة. ما اتجاه دوران الترس ٥؟', '/assets/bunyan/mawhiba2/a-s17.png', '[{"text":"عكس عقارب الساعة"},{"text":"باتجاه عقارب الساعة"},{"text":"لا يدور"},{"text":"يتوقف بعد دورة"}]', 1, 'الأتراس الفردية (١، ٣، ٥) تدور في اتجاه واحد، والزوجية في الاتجاه المعاكس. الترس ٥ يدور باتجاه عقارب الساعة.', '["mawhiba_l2","mawhiba_l2#89"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('ff618a85-e21a-50a7-afca-11f71e60849d', 'scientific', 'قوى', 'mawhiba_l2', 'medium', 'text', 'دُفع صندوق على أرض ملساء فاستمر في الحركة بسرعة ثابتة تقريباً. ما أنسب تفسير؟', NULL, '[{"text":"قوة الدفع تزداد باستمرار"},{"text":"الجاذبية توقفت"},{"text":"الصندوق يخلق طاقة"},{"text":"لا توجد قوة احتكاك كبيرة تبطئه"}]', 3, 'الجسم يحافظ على حركته ما لم تؤثر عليه قوة خارجية مثل الاحتكاك (قانون القصور الذاتي).', '["mawhiba_l2","mawhiba_l2#90"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('f7162f65-a803-521b-a62e-cc8d95fc6104', 'scientific', 'مادة', 'mawhiba_l2', 'easy', 'text', 'إذا كانت كثافة قطعة خشب أقل من كثافة الماء، فماذا نتوقع عند وضعها في ماء؟', NULL, '[{"text":"تغوص"},{"text":"تذوب"},{"text":"تتبخر"},{"text":"تطفو"}]', 3, 'الجسم الأقل كثافة من السائل يطفو عليه.', '["mawhiba_l2","mawhiba_l2#91"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('c2b25fc4-0b7e-5f6c-a871-b7a4c74e6a48', 'scientific', 'تروس', 'mawhiba_l2', 'medium', 'image', 'ترس صغير عدد أسنانه ١٢ يعشّق ترساً كبيراً عدد أسنانه ٢٤. إذا دار الترس الصغير ٦ دورات، فكم دورة يدورها الترس الكبير؟', '/assets/bunyan/mawhiba2/a-s20.png', '[{"text":"١٢"},{"text":"٦"},{"text":"٣"},{"text":"٢"}]', 2, 'عدد الأسنان المارة متساوٍ: ٦ × ١٢ = ٧٢ سنّاً، والترس الكبير ٢٤ سنّاً فيدور ٧٢ ÷ ٢٤ = ٣ دورات.', '["mawhiba_l2","mawhiba_l2#92"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('95c8de7c-17d3-5203-a54e-ffbf35d7372b', 'scientific', 'طاقة', 'mawhiba_l2', 'medium', 'text', 'كرة تتدحرج من أعلى منحدر إلى أسفله. ماذا يحدث لطاقتها بين القمة والأسفل؟', NULL, '[{"text":"طاقة الحركة تتحول إلى وضع"},{"text":"تزداد طاقة الوضع"},{"text":"تختفي الطاقة"},{"text":"طاقة الوضع تتحول إلى طاقة حركة"}]', 3, 'عند الهبوط تقل طاقة الوضع وتزداد طاقة الحركة.', '["mawhiba_l2","mawhiba_l2#93"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('8ed72f62-8afe-5546-ab66-7b88c0cf6864', 'scientific', 'مادة', 'mawhiba_l2', 'medium', 'text', 'كتلة مكعب ٢٠٠ غ وحجمه ٥٠ سم³. ما كثافته؟', NULL, '[{"text":"٠٫٢٥ غ/سم³"},{"text":"١٠٠٠٠ غ/سم³"},{"text":"٤ غ/سم³"},{"text":"٢٥٠ غ/سم³"}]', 2, 'الكثافة = الكتلة ÷ الحجم = ٢٠٠ ÷ ٥٠ = ٤ غ/سم³.', '["mawhiba_l2","mawhiba_l2#94"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('de2655c9-32f3-5fe7-a071-a739f957e7e3', 'scientific', 'كهرباء', 'mawhiba_l2', 'easy', 'text', 'أي المواد التالية موصلة للكهرباء؟', NULL, '[{"text":"مسطرة بلاستيكية"},{"text":"كوب زجاجي"},{"text":"سلك نحاسي"},{"text":"قطعة خشب جافة"}]', 2, 'النحاس فلز جيد التوصيل.', '["mawhiba_l2","mawhiba_l2#95"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('3d4f3612-7b90-5a80-ad17-304e94df7b4f', 'scientific', 'أحياء', 'mawhiba_l2', 'easy', 'text', 'أي من السلوكيات التالية سلوك مكتسب وليس غريزياً؟', NULL, '[{"text":"رمش العين"},{"text":"ركوب الدراجة"},{"text":"انقباض البؤبؤ في الضوء"},{"text":"سحب اليد عن النار"}]', 1, 'ركوب الدراجة يُتعلّم بالتدريب، والباقي أفعال لا إرادية.', '["mawhiba_l2","mawhiba_l2#96"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a9331a90-7e36-5848-aac1-8a64f89608e2', 'verbal', 'تناظر', 'mawhiba_l2', 'medium', 'text', 'حرارة : ميزان الحرارة  ::  زمن : ؟', NULL, '[{"text":"يوم"},{"text":"ساعة"},{"text":"دقيقة"},{"text":"تاريخ"}]', 1, 'العلاقة: ما يُقاس وأداة قياسه.', '["mawhiba_l2","mawhiba_l2#97"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('ef1481f9-72ae-5338-a728-a53eedd31c1b', 'verbal', 'إكمال', 'mawhiba_l2', 'medium', 'text', 'اختر الكلمة المعاكسة في المعنى لـ «شحّ»:', NULL, '[{"text":"وفرة"},{"text":"ندرة"},{"text":"قلة"},{"text":"نقص"}]', 0, 'الشحّ قلة، وضده الوفرة.', '["mawhiba_l2","mawhiba_l2#98"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('423fa5e0-98c4-571b-aadf-67d0b3868ea0', 'verbal', 'تناظر', 'mawhiba_l2', 'medium', 'text', 'فصل : سنة  ::  شهر : ؟', NULL, '[{"text":"فصل"},{"text":"يوم"},{"text":"أسبوع"},{"text":"ساعة"}]', 0, 'العلاقة: جزء وما يتكوّن منه. الشهر جزء من الفصل.', '["mawhiba_l2","mawhiba_l2#99"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('5a709d98-45a9-5619-a7bc-a0c7c3db6fb1', 'verbal', 'استنتاج', 'mawhiba_l2', 'hard', 'text', '«ما كل ما يتمناه المرء يدركه». أقرب معنى للعبارة:', NULL, '[{"text":"كل الرغبات تتحقق"},{"text":"المرء لا يتمنى"},{"text":"التمني مستحيل"},{"text":"ليست كل الرغبات تتحقق"}]', 3, 'النفي مع «كل» يعني أن بعض الرغبات لا تتحقق، لا أن كلها لا تتحقق.', '["mawhiba_l2","mawhiba_l2#100"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('b768126f-fd5b-58e3-afe7-a8c018cdb0e2', 'verbal', 'تناظر', 'mawhiba_l2', 'medium', 'text', 'شحيح : كريم  ::  متواضع : ؟', NULL, '[{"text":"خجول"},{"text":"هادئ"},{"text":"متكبر"},{"text":"طموح"}]', 2, 'العلاقة: ضدان.', '["mawhiba_l2","mawhiba_l2#101"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('038e7619-879a-5e22-a270-89abe2bad4e3', 'verbal', 'إكمال', 'mawhiba_l2', 'easy', 'text', 'جملة واحدة فقط تحمل معنى «التأجيل»، فما هي؟', NULL, '[{"text":"أنهيت المشروع أمس."},{"text":"أكمل المشروع الآن."},{"text":"سأكمل المشروع غداً بدل اليوم."},{"text":"لن أبدأ المشروع أبداً."}]', 2, 'التأجيل هو نقل العمل إلى وقت لاحق، وهذا ما تقوله الجملة الأولى.', '["mawhiba_l2","mawhiba_l2#102"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a34835dd-6af4-591a-a632-0a246c5f1d27', 'verbal', 'إكمال', 'mawhiba_l2', 'medium', 'text', 'معنى «يُجادل» في الجملة: «يُجادل الطالبُ معلمه بالحجة والدليل» هو:', NULL, '[{"text":"يغضب"},{"text":"يتجاهل"},{"text":"يناقش ليقنع"},{"text":"يوافق"}]', 2, 'السياق «بالحجة والدليل» يدل على نقاش بقصد الإقناع.', '["mawhiba_l2","mawhiba_l2#103"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('abd16565-6507-5fbe-a404-bdaf2d3c408b', 'verbal', 'تناظر', 'mawhiba_l2', 'medium', 'text', 'مجرفة : حفر  ::  منشار : ؟', NULL, '[{"text":"قطع الخشب"},{"text":"حدّاد"},{"text":"مسمار"},{"text":"غابة"}]', 0, 'العلاقة: أداة ووظيفتها.', '["mawhiba_l2","mawhiba_l2#104"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('989c378b-9cb3-5d7a-a539-a24867bfe2f0', 'verbal', 'المختلف', 'mawhiba_l2', 'medium', 'text', 'أي الكلمات لا تناسب باقي الكلمات؟', NULL, '[{"text":"يكتب"},{"text":"يتحدث"},{"text":"يرسم"},{"text":"يخط"}]', 1, 'يكتب ويرسم ويخط أفعال تترك أثراً على سطح، أما يتحدث فلا يترك أثراً مكتوباً.', '["mawhiba_l2","mawhiba_l2#105"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('1be09a8a-1580-5f24-acad-110eda4f8eba', 'verbal', 'تناظر', 'mawhiba_l2', 'easy', 'text', 'جائع : طعام  ::  عطشان : ؟', NULL, '[{"text":"كوب"},{"text":"نهر"},{"text":"بحر"},{"text":"ماء"}]', 3, 'العلاقة: حالة والشيء الذي يزيلها.', '["mawhiba_l2","mawhiba_l2#106"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('e21f10f7-b775-5b5a-a531-88cf5e7f7cde', 'verbal', 'إكمال', 'mawhiba_l2', 'medium', 'text', 'اختر الكلمة المناسبة: «لم يكن قراره ........، بل جاء بعد دراسة طويلة للخيارات».', NULL, '[{"text":"مدروساً"},{"text":"حكيماً"},{"text":"متسرعاً"},{"text":"متأنياً"}]', 2, '«بل» تنفي ما قبلها وتثبت ما بعدها «دراسة طويلة»، فالمنفي هو التسرع.', '["mawhiba_l2","mawhiba_l2#107"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('59fec664-0122-5090-a438-3186ee3bf6b7', 'verbal', 'إكمال', 'mawhiba_l2', 'easy', 'text', '«العلم نور، و........ ظلام». اختر الكلمة المناسبة:', NULL, '[{"text":"الدرس"},{"text":"القلم"},{"text":"النوم"},{"text":"الجهل"}]', 3, 'علاقة تضاد: العلم والجهل.', '["mawhiba_l2","mawhiba_l2#108"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('f079377b-b9f5-5c2b-ae5e-b23e0a13e2fd', 'verbal', 'استنتاج', 'mawhiba_l2', 'hard', 'text', 'إذا كان «كل المتفوقين يذاكرون» و«سعد لا يذاكر»، فماذا نستنتج؟', NULL, '[{"text":"سعد متفوق"},{"text":"سعد يحب الدراسة"},{"text":"كل من يذاكر متفوق"},{"text":"سعد ليس متفوقاً"}]', 3, 'من لا يذاكر لا يحقق شرط المتفوق، فسعد ليس متفوقاً. أما «كل من يذاكر متفوق» فلا يلزم من المعطيات.', '["mawhiba_l2","mawhiba_l2#109"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('2789a89a-d9b8-5f09-ac0b-0894e0c3d093', 'verbal', 'تناظر', 'mawhiba_l2', 'easy', 'text', 'حذر : تهوّر  ::  كرم : ؟', NULL, '[{"text":"جود"},{"text":"بخل"},{"text":"سخاء"},{"text":"عطاء"}]', 1, 'العلاقة: ضدان. التهور ضد الحذر، والبخل ضد الكرم.', '["mawhiba_l2","mawhiba_l2#110"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a8a9e356-4114-5564-ab94-079419da1d9d', 'verbal', 'تناظر', 'mawhiba_l2', 'easy', 'text', 'قلم : كتابة  ::  مقص : ؟', NULL, '[{"text":"ورق"},{"text":"حدّة"},{"text":"خياطة"},{"text":"قص"}]', 3, 'العلاقة: أداة ووظيفتها المباشرة، ووظيفة المقص القص.', '["mawhiba_l2","mawhiba_l2#111"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('6ff7c104-af3b-5b18-aff3-eef02d5b63da', 'verbal', 'فهم المقروء', 'mawhiba_l2', 'easy', 'text', '📖 كيف تتكون السحب
تتكوّن السحب عندما يتبخر الماء من البحار والأنهار بفعل حرارة الشمس، ثم يصعد بخار الماء إلى طبقات أبرد في الجو. هناك يتكاثف على ذرات صغيرة من الغبار فيصير قطرات دقيقة جداً، وتتجمع ملايين القطرات فنراها سحابة. وعندما تكبر القطرات وتثقل لا يستطيع الهواء حملها فتسقط مطراً.

ما السبب المباشر لتكاثف بخار الماء إلى قطرات؟', NULL, '[{"text":"هبوب الرياح القوية"},{"text":"زيادة حرارة الشمس"},{"text":"نزول المطر"},{"text":"وصوله إلى طبقات أبرد"}]', 3, 'النص يقول إنه يصعد إلى طبقات أبرد ثم يتكاثف.', '["mawhiba_l2","mawhiba_l2#112"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('0413bf71-a83c-5256-a9be-cc7be3ede493', 'verbal', 'فهم المقروء', 'mawhiba_l2', 'medium', 'text', '📖 كيف تتكون السحب
تتكوّن السحب عندما يتبخر الماء من البحار والأنهار بفعل حرارة الشمس، ثم يصعد بخار الماء إلى طبقات أبرد في الجو. هناك يتكاثف على ذرات صغيرة من الغبار فيصير قطرات دقيقة جداً، وتتجمع ملايين القطرات فنراها سحابة. وعندما تكبر القطرات وتثقل لا يستطيع الهواء حملها فتسقط مطراً.

لماذا يسقط المطر من السحابة بحسب النص؟', NULL, '[{"text":"لأن القطرات تكبر وتثقل"},{"text":"لأن الشمس تختفي"},{"text":"لأن الغبار يزول"},{"text":"لأن البحار تجف"}]', 0, 'النص: عندما تكبر القطرات وتثقل لا يحملها الهواء.', '["mawhiba_l2","mawhiba_l2#113"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a968d89d-99e3-56cf-a49f-740eaf45cc52', 'verbal', 'فهم المقروء', 'mawhiba_l2', 'medium', 'text', '📖 كيف تتكون السحب
تتكوّن السحب عندما يتبخر الماء من البحار والأنهار بفعل حرارة الشمس، ثم يصعد بخار الماء إلى طبقات أبرد في الجو. هناك يتكاثف على ذرات صغيرة من الغبار فيصير قطرات دقيقة جداً، وتتجمع ملايين القطرات فنراها سحابة. وعندما تكبر القطرات وتثقل لا يستطيع الهواء حملها فتسقط مطراً.

أي عبارة لا يدعمها النص؟', NULL, '[{"text":"الغبار يساعد على التكاثف"},{"text":"القطرات الصغيرة تتجمع في السحابة"},{"text":"الشمس تسبب التبخر"},{"text":"السحب تتكون من الجليد فقط"}]', 3, 'النص لا يذكر أن السحب جليد فقط؛ ذكر قطرات الماء.', '["mawhiba_l2","mawhiba_l2#114"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('d9ecae46-4f92-50c7-a09f-ee28670df98c', 'verbal', 'فهم المقروء', 'mawhiba_l2', 'medium', 'text', '📖 القطط والسهر
تنشط القطط في الفجر والغروب أكثر من منتصف النهار، لأن أسلافها البرية كانت تصطاد القوارض في هذين الوقتين. وعيون القطط تحتوي على طبقة تعكس الضوء، فتستفيد من الضوء الخافت. لكن هذا لا يعني أنها ترى في الظلام التام؛ فهي تحتاج إلى قدر ضئيل من الضوء.

ما سبب نشاط القطط عند الفجر والغروب بحسب النص؟', NULL, '[{"text":"لأنها تخاف الشمس"},{"text":"لأنها لا تشرب الماء"},{"text":"هذه عادة ورثتها من أسلافها التي كانت تصطاد فيها"},{"text":"لأنها نائمة طوال الليل"}]', 2, 'النص يربط النشاط بصيد الأسلاف في هذين الوقتين.', '["mawhiba_l2","mawhiba_l2#115"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('57be360e-dd7a-5045-a49d-c22fa0070328', 'verbal', 'فهم المقروء', 'mawhiba_l2', 'easy', 'text', '📖 القطط والسهر
تنشط القطط في الفجر والغروب أكثر من منتصف النهار، لأن أسلافها البرية كانت تصطاد القوارض في هذين الوقتين. وعيون القطط تحتوي على طبقة تعكس الضوء، فتستفيد من الضوء الخافت. لكن هذا لا يعني أنها ترى في الظلام التام؛ فهي تحتاج إلى قدر ضئيل من الضوء.

ما الذي يساعد القطط على الاستفادة من الضوء الخافت؟', NULL, '[{"text":"الشوارب الطويلة"},{"text":"طبقة في العين تعكس الضوء"},{"text":"الفراء الكثيف"},{"text":"الأذن الصغيرة"}]', 1, 'ذكر النص الطبقة العاكسة في العين.', '["mawhiba_l2","mawhiba_l2#116"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('f1c8ed4c-0488-528f-a23a-5a5e1ff2cd70', 'verbal', 'فهم المقروء', 'mawhiba_l2', 'medium', 'text', '📖 القطط والسهر
تنشط القطط في الفجر والغروب أكثر من منتصف النهار، لأن أسلافها البرية كانت تصطاد القوارض في هذين الوقتين. وعيون القطط تحتوي على طبقة تعكس الضوء، فتستفيد من الضوء الخافت. لكن هذا لا يعني أنها ترى في الظلام التام؛ فهي تحتاج إلى قدر ضئيل من الضوء.

أي استنتاج صحيح؟', NULL, '[{"text":"القطط ترى في الظلام التام"},{"text":"القطط لا ترى في ظلام تام تماماً"},{"text":"القطط تصطاد الأسماك فقط"},{"text":"القطط لا تحتاج إلى ضوء"}]', 1, 'النص صرح أنها تحتاج قدراً ضئيلاً من الضوء.', '["mawhiba_l2","mawhiba_l2#117"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('8f7c7915-ec1d-5924-af37-aa56a492576f', 'verbal', 'فهم المقروء', 'mawhiba_l2', 'medium', 'text', '📖 الصبر والنحلة
تحتاج النحلة العاملة إلى زيارة نحو ألفي زهرة لتجمع ما يكفي من الرحيق لملء معدتها الخاصة بالرحيق، ثم تعود إلى الخلية لتفرغ ما جمعته. وتقوم نحلات أخريات بتحويل الرحيق إلى عسل بتبخير الماء منه وإضافة مواد خاصة. ولذلك لا تنتج النحلة الواحدة طوال حياتها إلا مقداراً صغيراً جداً من العسل.

ما فائدة تبخير الماء من الرحيق؟', NULL, '[{"text":"يتحول الرحيق إلى عسل"},{"text":"يصير أكثر حلاوة فقط"},{"text":"تموت النحلة"},{"text":"تزداد الأزهار"}]', 0, 'النص: تحوّل الرحيق إلى عسل بتبخير الماء وإضافة مواد.', '["mawhiba_l2","mawhiba_l2#118"]', 1, 'mawhiba_l2');
