تحتاج النحلة العاملة إلى زيارة نحو ألفي زهرة لتجمع ما يكفي من الرحيق لملء معدتها الخاصة بالرحيق، ثم تعود إلى الخلية لتفرغ ما جمعته. وتقوم نحلات أخريات بتحويل الرحيق إلى عسل بتبخير الماء منه وإضافة مواد خاصة. ولذلك لا تنتج النحلة الواحدة طوال حياتها إلا مقداراً صغيراً جداً من العسل.

من الذي يحوّل الرحيق إلى عسل؟', NULL, '[{"text":"النحلة التي جمعته وحدها"},{"text":"الأزهار نفسها"},{"text":"نحلات أخريات في الخلية"},{"text":"ملكة الخلية"}]', 2, 'النص: «تقوم نحلات أخريات».', '["mawhiba_l2","mawhiba_l2#119"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('f54c7a59-0ff8-534d-a7ad-40aafce3e5c0', 'verbal', 'فهم المقروء', 'mawhiba_l2', 'hard', 'text', '📖 الصبر والنحلة
تحتاج النحلة العاملة إلى زيارة نحو ألفي زهرة لتجمع ما يكفي من الرحيق لملء معدتها الخاصة بالرحيق، ثم تعود إلى الخلية لتفرغ ما جمعته. وتقوم نحلات أخريات بتحويل الرحيق إلى عسل بتبخير الماء منه وإضافة مواد خاصة. ولذلك لا تنتج النحلة الواحدة طوال حياتها إلا مقداراً صغيراً جداً من العسل.

ماذا يدل عليه عدد الأزهار المذكور في النص (نحو ألفي زهرة)؟', NULL, '[{"text":"أن الأزهار قليلة جداً"},{"text":"أن العسل يُصنع في الأزهار"},{"text":"أن النحلة تعمل ساعة واحدة"},{"text":"أن جمع الرحيق عمل شاق يحتاج زيارات كثيرة"}]', 3, 'الرقم الكبير يدل على كثرة الزيارات اللازمة لملء معدة الرحيق.', '["mawhiba_l2","mawhiba_l2#120"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('9fc71b31-31f3-56db-a6a4-bd88353f3d2b', 'flexibility', 'إعادة صياغة', 'mawhiba_l2', 'medium', 'text', 'أي تغيير في حياة المدينة يمكنه أن يقلل الازدحام ويقلل التلوث معاً؟', NULL, '[{"text":"زيادة عدد المواقف فقط"},{"text":"إغلاق المدارس"},{"text":"منع المشي"},{"text":"زيادة وسائل النقل العام السريعة"}]', 3, 'النقل العام يقلل عدد السيارات فيقل الازدحام والعوادم.', '["mawhiba_l2","mawhiba_l2#121"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('eb45d2b3-6652-5d92-a49c-eae096b0ef52', 'flexibility', 'حل مشكلات', 'mawhiba_l2', 'hard', 'text', 'عندك مصباحان ومفتاحان على لوحة ولا تدري أي مفتاح لأي مصباح، ويمكنك الدخول للغرفة مرة واحدة. أفضل خطة:', NULL, '[{"text":"تشغل المفتاح الأول وتنتظر ثم تطفئه وتشغل الثاني وتدخل، فالمضيء للثاني والدافئ المطفأ للأول"},{"text":"تدخل مباشرة وتخمن"},{"text":"تشغل المفتاحين وتدخل"},{"text":"لا يمكن معرفة ذلك"}]', 0, 'المصباح الدافئ المطفأ يدل على أنه كان مرتبطاً بالمفتاح الأول.', '["mawhiba_l2","mawhiba_l2#122"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('929ed4bb-dcef-5790-afed-96c1504e9084', 'flexibility', 'تبديل القاعدة', 'mawhiba_l2', 'medium', 'text', 'ما الحد التالي: ٢، ٥، ٤، ٧، ٦، ٩، ٨، ؟', NULL, '[{"text":"١١"},{"text":"١٠"},{"text":"٩"},{"text":"١٢"}]', 0, 'نبدل: +٣ ثم −١. ٨ + ٣ = ١١.', '["mawhiba_l2","mawhiba_l2#123"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('e4cf9724-67c1-5f13-ac67-78c9e4c65c4e', 'flexibility', 'تبديل القاعدة', 'mawhiba_l2', 'easy', 'text', 'ما الحد التالي: ٣، ٦، ١٢، ٢٤، ٤٨، ٩٦، ؟', NULL, '[{"text":"١٩٢"},{"text":"١٤٤"},{"text":"١٠٠"},{"text":"١٢٨"}]', 0, 'كل حد ضعف السابق.', '["mawhiba_l2","mawhiba_l2#124"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('29e2a236-ea17-5d1b-a62c-03850d0a82b7', 'flexibility', 'أفكار', 'mawhiba_l2', 'easy', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: حبل الغسيل.', NULL, '[{"text":"نشر المناشف"},{"text":"تعليق الملابس"},{"text":"نشر الأغطية"},{"text":"ربط قارب بالرصيف"}]', 3, 'الثلاثة تجفيف الأشياء بالتعليق، والمختلف الربط والتثبيت.', '["mawhiba_l2","mawhiba_l2#125"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('25bbf883-4ff1-5558-aab0-8c5c9c8503ef', 'flexibility', 'أفكار', 'mawhiba_l2', 'hard', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: الإسفنجة.', NULL, '[{"text":"حشو صندوق لحماية الأشياء الهشة عند النقل"},{"text":"مسح الطاولة"},{"text":"تنظيف الزجاج"},{"text":"امتصاص الماء المسكوب"}]', 0, 'الثلاثة للتنظيف والامتصاص، والمختلف للحماية بامتصاص الصدمات.', '["mawhiba_l2","mawhiba_l2#126"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('e997f817-5fb5-5417-a14c-79194842a423', 'flexibility', 'تصنيف', 'mawhiba_l2', 'easy', 'text', 'أي كلمة تنتمي إلى مجموعة «ما يُقاس بالزمن»: يوم، ساعة، ثانية، ؟', NULL, '[{"text":"متر"},{"text":"ليتر"},{"text":"أسبوع"},{"text":"كيلوغرام"}]', 2, 'اليوم والساعة والثانية والأسبوع كلها وحدات زمن.', '["mawhiba_l2","mawhiba_l2#127"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('236684ab-5282-5e0b-a484-277508433862', 'flexibility', 'إعادة صياغة', 'mawhiba_l2', 'medium', 'text', 'لديك حبل قصير ولا تصل إلى ثمرة عالية. أي فكرة جديدة تحل المشكلة؟', NULL, '[{"text":"ربط ثقل في طرفه وإلقاؤه فوق الغصن لسحبه"},{"text":"الصياح عليها"},{"text":"الانتظار حتى تسقط وحدها فقط"},{"text":"قطع الحبل"}]', 0, 'استعمال الحبل بطريقة جديدة لحل المشكلة.', '["mawhiba_l2","mawhiba_l2#128"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('22254437-9c28-587f-ab60-e5154ef6f269', 'flexibility', 'تصنيف', 'mawhiba_l2', 'easy', 'text', 'أي ترتيب يمكن اعتماده لترتيب: «مليون، ألف، مئة، عشرة» من الأكبر؟', NULL, '[{"text":"ألف، مئة، مليون، عشرة"},{"text":"مليون، ألف، مئة، عشرة"},{"text":"عشرة، مئة، ألف، مليون"},{"text":"مئة، ألف، عشرة، مليون"}]', 1, 'الترتيب التنازلي بحسب القيمة العددية.', '["mawhiba_l2","mawhiba_l2#129"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('4c78d063-d2b1-5411-ac00-b560418d75d0', 'flexibility', 'حل مشكلات', 'mawhiba_l2', 'medium', 'text', 'ماذا تفعل إذا سقط مفتاحك في أنبوب ضيق عميق ولا تصل إليه اليد؟', NULL, '[{"text":"تكسر الأنبوب فوراً"},{"text":"تنتظر أن يخرج وحده"},{"text":"تصب الماء فقط دون تفكير"},{"text":"تصنع أداة التقاط بسلك مثني أو مغناطيس ملصق بخيط"}]', 3, 'حل عملي يستخدم أدوات متاحة بأقل ضرر.', '["mawhiba_l2","mawhiba_l2#130"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('59a2a570-a47b-5e96-a95b-8d90a671d6a6', 'flexibility', 'أفكار', 'mawhiba_l2', 'medium', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: قارورة بلاستيكية فارغة.', NULL, '[{"text":"قصها وجعلها حاوية للأقلام"},{"text":"جعلها وعاءً للمشابك"},{"text":"استعمالها عوّامة طافية"},{"text":"استعمالها إناءً لحفظ البراغي"}]', 2, 'ثلاثة استخدامات تعتمد على فكرة الوعاء والتخزين، والرابع يعتمد على الطفو.', '["mawhiba_l2","mawhiba_l2#131"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('27bb9570-daf3-5226-a02e-3a27ba064523', 'flexibility', 'حل مشكلات', 'mawhiba_l2', 'hard', 'text', 'يريد طالب ترتيب ٤ كتب على رف بحيث لا يكون الكتاب الأحمر أول الصف. كم ترتيباً ممكناً؟', NULL, '[{"text":"١٨"},{"text":"٢٤"},{"text":"٦"},{"text":"١٢"}]', 0, 'الكلي ٤! = ٢٤، ولو كان الأحمر الأول ٣! = ٦. إذن ٢٤ − ٦ = ١٨.', '["mawhiba_l2","mawhiba_l2#132"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('1b5683b9-74b5-5685-a575-39af74a18164', 'flexibility', 'تصنيف', 'mawhiba_l2', 'easy', 'text', 'أي مجموعة يمكن أن تُسمّى «أشياء تُفتح وتُغلق»؟', NULL, '[{"text":"مسطرة، قلم، كرسي"},{"text":"ماء، هواء، تراب"},{"text":"صخرة، جبل، وادي"},{"text":"باب، كتاب، حقيبة، علبة"}]', 3, 'الباب والكتاب والحقيبة والعلبة تُفتح وتُغلق.', '["mawhiba_l2","mawhiba_l2#133"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('23a8a318-965a-5a61-a4ae-e11fdd79a631', 'flexibility', 'تبديل القاعدة', 'mawhiba_l2', 'easy', 'text', 'في الصف: ٣ أ، ٦ ب، ٩ ج، ١٢ د، ؟', NULL, '[{"text":"١٥ و"},{"text":"١٥ هـ"},{"text":"١٨ هـ"},{"text":"١٤ هـ"}]', 1, 'الأعداد تزيد ٣ والحروف تتتالى هجائياً: ١٥ هـ.', '["mawhiba_l2","mawhiba_l2#134"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('e1776896-b9ac-53af-accf-5b51f4cceee8', 'flexibility', 'أفكار', 'mawhiba_l2', 'medium', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: المرآة.', NULL, '[{"text":"توجيه ضوء الشمس إلى زاوية مظلمة"},{"text":"تزيين جدار"},{"text":"إرسال إشارة ضوئية"},{"text":"رؤية الأشياء خلف الزاوية"}]', 1, 'الثلاثة تستعمل خاصية انعكاس الضوء، والمختلف زخرفي.', '["mawhiba_l2","mawhiba_l2#135"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('126b7359-4334-5544-a803-686c5205086a', 'flexibility', 'إعادة صياغة', 'mawhiba_l2', 'hard', 'text', 'خمس أفكار مختلفة لاستعمال إطار سيارة قديم. أي ثلاث منها مختلفة الجنس (ليست كلها من نفس النوع)؟', NULL, '[{"text":"أرجوحة، أرجوحة أخرى، أرجوحة معلقة"},{"text":"كرسي، كرسي صغير، مقعد"},{"text":"حوض زراعة، حوض نباتات، حوض ورد"},{"text":"أرجوحة، حوض زراعة، حاجز ملعب"}]', 3, 'المرونة تعني التنويع في النوع: ترفيه وزراعة وحماية.', '["mawhiba_l2","mawhiba_l2#136"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('489f00fb-3088-5284-a805-4745e1150d73', 'flexibility', 'تصنيف', 'mawhiba_l2', 'medium', 'text', 'الأشياء: كرة سلة، برتقالة، إطار، قمر. ما الخاصية التي تجمعها؟', NULL, '[{"text":"الأكل"},{"text":"شكل كروي أو دائري"},{"text":"اللون البرتقالي"},{"text":"الاستخدام الرياضي فقط"}]', 1, 'كرة السلة والبرتقالة والقمر كروية، والإطار دائري. أما الأكل أو اللون أو الرياضة فلا يشملها جميعاً.', '["mawhiba_l2","mawhiba_l2#137"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('1fbd540a-0f39-5f1f-a21d-79496d1adf25', 'flexibility', 'حل مشكلات', 'mawhiba_l2', 'hard', 'text', 'لدى طالب إناءان بلا تدريج: سعة الأول ٥ لترات والثاني ٣ لترات، ومعهما ماء كافٍ. كيف يقيس ٤ لترات بالضبط؟', NULL, '[{"text":"يملأ ٣ ويضيف نصف ٥"},{"text":"يملأ ٥، يصب منه في ٣، يفرغ الـ٣، يصب الـ٢ المتبقية فيه، يملأ ٥ ويكمل الـ٣ فيبقى ٤"},{"text":"يملأ ٥ ويسكب الثلث"},{"text":"لا يمكن قياس ٤ لترات"}]', 1, '٥ → ٣ يبقى ٢ في الأول. أفرغ الثاني، صب الـ٢ فيه. املأ الأول ٥ وصب في الثاني حتى يمتلئ (يتسع لتر واحد) فيبقى ٤ في الأول.', '["mawhiba_l2","mawhiba_l2#138"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('6d24cc27-fa1d-535f-a609-b250dff2c4c4', 'flexibility', 'تصنيف', 'mawhiba_l2', 'medium', 'text', 'أي كلمة يمكن تصنيفها مرة مع «حيوانات» ومرة مع «حشرات»؟', NULL, '[{"text":"نحلة"},{"text":"أسد"},{"text":"وردة"},{"text":"سمكة"}]', 0, 'النحلة حيوان وحشرة في آن واحد. الأسد حيوان لكنه ليس حشرة.', '["mawhiba_l2","mawhiba_l2#139"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('3b82f9f2-c7ea-56b2-aec7-daec8c0658ae', 'flexibility', 'أفكار', 'mawhiba_l2', 'medium', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: كوب زجاجي.', NULL, '[{"text":"شرب الماء"},{"text":"شرب العصير"},{"text":"سكب الحليب"},{"text":"تضخيم الصوت بوضعه مقلوباً على الجدار والاستماع"}]', 3, 'الثلاثة للشرب، والمختلف استعماله للتضخيم والاستماع.', '["mawhiba_l2","mawhiba_l2#140"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('7d02e493-dadf-582d-a9ad-bbcb04b5fd3f', 'flexibility', 'تبديل القاعدة', 'mawhiba_l2', 'medium', 'text', 'أي رقم يكمل: ٥ ، ٤ ، ١٠ ، ٨ ، ١٥ ، ١٢ ، ٢٠ ، ؟', NULL, '[{"text":"١٥"},{"text":"١٨"},{"text":"١٦"},{"text":"٢٥"}]', 2, 'الحدود الفردية مضاعفات ٥ (٥، ١٠، ١٥، ٢٠) والزوجية مضاعفات ٤ (٤، ٨، ١٢، ١٦).', '["mawhiba_l2","mawhiba_l2#141"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('db6e8d3e-5c3e-5771-a0ae-cdc687dfa0f5', 'flexibility', 'تصنيف', 'mawhiba_l2', 'easy', 'text', 'يمكن تصنيف «البيضة» مع الأطعمة الغنية بالبروتين، ويمكن تصنيفها أيضاً مع:', NULL, '[{"text":"الأشياء الصلبة فقط"},{"text":"الأشياء التي تخرج من الدجاجة"},{"text":"الفواكه"},{"text":"المعادن"}]', 1, 'البيضة غذاء بروتيني وهي من نتاج الدجاجة.', '["mawhiba_l2","mawhiba_l2#142"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('3abce639-37a7-58a3-aa9c-ff3e1f1b1c35', 'flexibility', 'تبديل القاعدة', 'mawhiba_l2', 'easy', 'text', 'أي زوج يكمل التتابع: (١،٢)، (٢،٤)، (٣،٦)، (٤،٨)، ؟', NULL, '[{"text":"(٥، ٩)"},{"text":"(٦، ١٢)"},{"text":"(٥، ١٠)"},{"text":"(٤، ١٠)"}]', 2, 'الثاني ضعف الأول، والأول يزيد واحداً.', '["mawhiba_l2","mawhiba_l2#143"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('b71460fe-40b2-52cf-a73d-a3984650b207', 'flexibility', 'أفكار', 'mawhiba_l2', 'medium', 'text', 'أربعة استخدامات مقترحة لشيء واحد. ثلاثة منها تقوم على الفكرة نفسها، وواحد يقوم على فكرة مختلفة. اختر المختلف. الشيء: علبة كرتون كبيرة.', NULL, '[{"text":"صندوق لتخزين الألعاب"},{"text":"حاوية لحفظ الكتب القديمة"},{"text":"وعاء لجمع الأحذية"},{"text":"تحويلها إلى بيت للعب"}]', 3, 'الثلاثة للتخزين، والمختلف استخدام للّعب والخيال.', '["mawhiba_l2","mawhiba_l2#144"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('7f8eb45c-10e7-562b-a8d5-d0ac90a5351a', 'quantitative', 'حساب', 'mawhiba_l2', 'medium', 'text', 'عبّأ بائع ١٢٥ برتقالة في صناديق، يتسع الصندوق لـ ١٢ برتقالة. كم صندوقاً يلزمه على الأقل؟', NULL, '[{"text":"١٠"},{"text":"١١"},{"text":"١٢"},{"text":"١٣"}]', 1, '١٢٥ ÷ ١٢ = ١٠ والباقي ٥، فنحتاج صندوقاً إضافياً، المجموع ١١.', '["mawhiba_l2","mawhiba_l2#145"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('a7c333cb-08f0-5028-ab69-b2ae1e8f73dd', 'quantitative', 'كسور', 'mawhiba_l2', 'hard', 'text', 'استهلكت أسرة ٣/٥ كمية الحليب في اليوم الأول، و١/٢ الباقي في اليوم الثاني. أي كسر من الكمية الأصلية بقي؟', NULL, '[{"text":"١/٥"},{"text":"٢/٥"},{"text":"١/١٠"},{"text":"٣/١٠"}]', 0, 'بعد اليوم الأول بقي ٢/٥. اليوم الثاني استهلك نصف ٢/٥ = ١/٥. بقي ٢/٥ − ١/٥ = ١/٥.', '["mawhiba_l2","mawhiba_l2#146"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('7361926f-50f5-5223-ab6c-2575d6bfa4db', 'quantitative', 'هندسة', 'mawhiba_l2', 'medium', 'text', 'يريد مزارع تسوير أرض مستطيلة بعرض ٨ م وطول ١٥ م، مع ترك باب عرضه ٢ م دون سور. كم متراً من السور يحتاج؟', NULL, '[{"text":"٤٦"},{"text":"٤٤"},{"text":"٤٨"},{"text":"١٢٠"}]', 1, 'المحيط = ٢(٨ + ١٥) = ٤٦، ناقص عرض الباب ٢ = ٤٤ م.', '["mawhiba_l2","mawhiba_l2#147"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('c3761f09-46b8-5977-abf9-a3f7c0a2ab7e', 'quantitative', 'متتاليات', 'mawhiba_l2', 'medium', 'text', 'ما العدد التالي: ٢، ٣، ٥، ٨، ١٢، ١٧، ؟', NULL, '[{"text":"٢٢"},{"text":"٢٤"},{"text":"٢٣"},{"text":"٢٥"}]', 2, 'الفروق ١، ٢، ٣، ٤، ٥ فالتالي ١٧ + ٦ = ٢٣.', '["mawhiba_l2","mawhiba_l2#148"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('ab9645e1-7625-5e06-aa11-0c1555af1066', 'quantitative', 'متتاليات', 'mawhiba_l2', 'hard', 'text', 'ما العدد التالي: ٣، ٥، ٩، ١٧، ٣٣، ؟', NULL, '[{"text":"٦٥"},{"text":"٤٩"},{"text":"٦٦"},{"text":"٦٤"}]', 0, 'الفروق: ٢، ٤، ٨، ١٦، فالتالي ٣٣ + ٣٢ = ٦٥.', '["mawhiba_l2","mawhiba_l2#149"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('43ef887a-af4f-565a-a04d-6d40a3d8f324', 'spatial', 'متتالية أشكال', 'mawhiba_l2', 'medium', 'image', 'يتغير اتجاه السهم في كل خطوة بزاوية ثابتة. أي الأشكال المرقمة يكمل المتتالية؟', '/assets/bunyan/mawhiba2/b-r6.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 0, 'السهم يدور في كل خطوة دورة ثابتة مقدارها ٩٠° عكس عقارب الساعة، فالشكل المطلوب هو رقم ١.', '["mawhiba_l2","mawhiba_l2#150"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('888656a8-fca8-57e8-a498-62e9e20a2dfc', 'spatial', 'مكعبات', 'mawhiba_l2', 'medium', 'image', 'يبيّن الشكل المنظر العلوي لمجموعة من مكعبات متطابقة مرصوصة فوق بعضها، والرقم في كل مربع هو عدد المكعبات في ذلك العمود. كم عدد المكعبات الكلي؟', '/assets/bunyan/mawhiba2/b-r7.png', '[{"text":"١٧"},{"text":"١٥"},{"text":"١٤"},{"text":"٢٠"}]', 1, 'نجمع الأرقام في كل المربعات: ٢ + ١ + ٣ + ١ + ٠ + ٢ + ٣ + ٢ + ١ = ١٥ مكعباً.', '["mawhiba_l2","mawhiba_l2#151"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('7c48545f-a882-53bc-a827-1423b15b6fbc', 'spatial', 'متتالية أشكال', 'mawhiba_l2', 'medium', 'image', 'يتغير اتجاه السهم في كل خطوة بزاوية ثابتة. أي الأشكال المرقمة يكمل المتتالية؟', '/assets/bunyan/mawhiba2/b-r8.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 1, 'السهم يدور في كل خطوة دورة ثابتة مقدارها ٩٠°، فالشكل المطلوب هو رقم ٢.', '["mawhiba_l2","mawhiba_l2#152"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('551f9413-290a-5333-a905-d0ea8fdc0542', 'quantitative', 'نسب', 'mawhiba_l2', 'medium', 'text', 'سعر قميص ٢٠٠ ريال خُفّض بنسبة ٢٥٪، ثم خُفّض السعر الجديد ٢٠ ريالاً. ما السعر النهائي؟', NULL, '[{"text":"١٥٠ ريالاً"},{"text":"١٢٥ ريالاً"},{"text":"١٣٠ ريالاً"},{"text":"١٨٠ ريالاً"}]', 2, 'بعد ٢٥٪: ٢٠٠ − ٥٠ = ١٥٠. ثم ١٥٠ − ٢٠ = ١٣٠ ريالاً.', '["mawhiba_l2","mawhiba_l2#153"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('5aa99391-8356-5bf4-a9ef-8bf429072d59', 'quantitative', 'إحصاء', 'mawhiba_l2', 'medium', 'text', 'إذا كان متوسط ثلاثة أعداد ١٥ وعددان منها ١٠ و٢٠، فما العدد الثالث؟', NULL, '[{"text":"١٠"},{"text":"٢٠"},{"text":"٢٥"},{"text":"١٥"}]', 3, 'المجموع = ٤٥، والعددان ٣٠، فالثالث ١٥.', '["mawhiba_l2","mawhiba_l2#154"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('114e1eed-6a09-52f1-ae23-cfc77b72d692', 'quantitative', 'تناسب', 'mawhiba_l2', 'medium', 'text', 'تقطع سيارة ٩٠ كم في ساعة ونصف. كم كيلومتراً تقطع في ٤ ساعات بنفس السرعة؟', NULL, '[{"text":"٢٤٠"},{"text":"٣٦٠"},{"text":"١٨٠"},{"text":"١٣٥"}]', 0, 'السرعة = ٩٠ ÷ ١٫٥ = ٦٠ كم/س، والمسافة = ٦٠ × ٤ = ٢٤٠ كم.', '["mawhiba_l2","mawhiba_l2#155"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('6ce1be87-3b3d-517c-a6f3-3806c76a124d', 'spatial', 'تدوير', 'mawhiba_l2', 'medium', 'image', 'يوضح الشكل في الأعلى نمطاً من المربعات الملونة. أي الأشكال المرقمة يمثل النمط بعد تدويره ٩٠° باتجاه عقارب الساعة؟', '/assets/bunyan/mawhiba2/b-r12.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 1, 'عند تدوير الشبكة ٩٠° باتجاه عقارب الساعة ينتقل كل مربع ملوّن إلى موضعه الجديد، والشكل رقم ٢ هو الناتج. الأشكال الأخرى تمثل تدويرات أخرى أو انعكاساً.', '["mawhiba_l2","mawhiba_l2#156"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('c40f1e64-538a-5f34-a4ba-19a8031047dd', 'quantitative', 'هندسة', 'mawhiba_l2', 'medium', 'text', 'مستطيل طوله ١٢ سم ومحيطه ٣٦ سم. كم مساحته بالسنتيمتر المربع؟', NULL, '[{"text":"٢١٦"},{"text":"٤٣٢"},{"text":"٨٤"},{"text":"٧٢"}]', 3, 'المحيط = ٢(ط + ع) = ٣٦ فط + ع = ١٨، فالعرض = ٦، والمساحة = ١٢ × ٦ = ٧٢.', '["mawhiba_l2","mawhiba_l2#157"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('7b6f76f7-3e8c-5d7c-a3f3-d3c7a9c36d58', 'spatial', 'مكعبات', 'mawhiba_l2', 'hard', 'image', 'يبيّن الشكل المنظر العلوي لمكعبات متطابقة مرصوصة، والرقم هو عدد المكعبات في العمود. والجهة الأمامية هي الحافة السفلية من الشكل. إذا نظرنا إلى المجسم من الأمام، فكم مربعاً تشغل صورته الأمامية (المسقط الأمامي)؟', '/assets/bunyan/mawhiba2/b-r14.png', '[{"text":"٨"},{"text":"٥"},{"text":"١٣"},{"text":"٧"}]', 3, 'المسقط الأمامي يأخذ في كل عمود أكبر ارتفاع بين الصفوف: ٣ + ٤ = ٧ مربعاً.', '["mawhiba_l2","mawhiba_l2#158"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('1f11b243-29e4-5b7b-ada3-2dcb066fc1c6', 'quantitative', 'هندسة', 'mawhiba_l2', 'easy', 'text', 'مربع مساحته ٨١ سم². كم محيطه بالسنتيمتر؟', NULL, '[{"text":"٣٦"},{"text":"١٨"},{"text":"٢٧"},{"text":"٨١"}]', 0, 'الضلع = ٩ لأن ٩ × ٩ = ٨١، والمحيط = ٤ × ٩ = ٣٦.', '["mawhiba_l2","mawhiba_l2#159"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('eba55e59-c915-5c64-a0f7-dd348c71341c', 'quantitative', 'احتمال', 'mawhiba_l2', 'medium', 'text', 'تحتوي حقيبة على ٥ كرات حمراء و٣ زرقاء و٢ خضراء. ما احتمال سحب كرة زرقاء؟', NULL, '[{"text":"٣/٥"},{"text":"١/٣"},{"text":"٣/١٠"},{"text":"٣/٧"}]', 2, 'عدد الكرات ١٠، والزرقاء ٣، فالاحتمال ٣/١٠.', '["mawhiba_l2","mawhiba_l2#160"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('0c466f26-b683-5645-a03e-ab7fe0ca97f7', 'quantitative', 'إحصاء', 'mawhiba_l2', 'hard', 'text', 'متوسط درجات ٤ اختبارات = ٧٥. ما الدرجة التي يحتاجها في الاختبار الخامس ليصبح المتوسط ٨٠؟', NULL, '[{"text":"٩٥"},{"text":"١٠٠"},{"text":"٨٠"},{"text":"٩٠"}]', 1, 'المجموع المطلوب = ٥ × ٨٠ = ٤٠٠، والحالي ٣٠٠، فيحتاج ١٠٠.', '["mawhiba_l2","mawhiba_l2#161"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('7e9059c9-ad08-5701-a054-9dc05533f05b', 'quantitative', 'تناسب', 'mawhiba_l2', 'easy', 'text', 'خُلط عصير تفاح بماء بنسبة ٢ : ٣. إذا كان الماء ١٢ لتراً، فكم لتراً من عصير التفاح؟', NULL, '[{"text":"١٨"},{"text":"٥"},{"text":"٨"},{"text":"١٠"}]', 2, '٣ أجزاء = ١٢ لتراً، فالجزء = ٤، وعصير التفاح ٢ × ٤ = ٨ لترات.', '["mawhiba_l2","mawhiba_l2#162"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('8c729ad9-5d9a-5183-a718-9069bddd6353', 'quantitative', 'تناسب', 'mawhiba_l2', 'hard', 'text', 'إذا كانت ٥ آلات تنتج ٥٠ قطعة في ساعة، فكم قطعة تنتج ٨ آلات في ساعتين؟', NULL, '[{"text":"٨٠"},{"text":"١٠٠"},{"text":"١٦٠"},{"text":"٢٥٠"}]', 2, 'الآلة الواحدة تنتج ١٠ قطع في الساعة، فـ ٨ آلات × ١٠ × ٢ = ١٦٠ قطعة.', '["mawhiba_l2","mawhiba_l2#163"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('ff1e2272-496e-535c-ad96-d58a8a2ef7bd', 'spatial', 'انعكاس', 'mawhiba_l2', 'medium', 'image', 'يوضع مرآة عمودية على الحافة اليمنى للشكل الظاهر في الأعلى. أي الأشكال المرقمة يمثل انعكاسه في المرآة؟', '/assets/bunyan/mawhiba2/b-r20.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 3, 'الانعكاس في مرآة عمودية يقلب الشكل يميناً ويساراً مع بقاء الأعلى والأسفل في مكانهما، والناتج هو الشكل رقم ٤.', '["mawhiba_l2","mawhiba_l2#164"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('dc1754f4-47bf-5523-a3fd-81a99e36bd80', 'spatial', 'متتالية أشكال', 'mawhiba_l2', 'medium', 'image', 'يتغير اتجاه السهم في كل خطوة بزاوية ثابتة. أي الأشكال المرقمة يكمل المتتالية؟', '/assets/bunyan/mawhiba2/b-r21.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 2, 'السهم يدور في كل خطوة دورة ثابتة مقدارها ٤٥°، فالشكل المطلوب هو رقم ٣.', '["mawhiba_l2","mawhiba_l2#165"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('2c2f75c2-6020-521b-a51e-ab37dd9d5d01', 'spatial', 'مصفوفة', 'mawhiba_l2', 'medium', 'image', 'في المصفوفة الظاهرة في الصورة قاعدة تحكم الصفوف والأعمدة. أي الأشكال المرقمة يكمل الخلية الناقصة (؟)؟', '/assets/bunyan/mawhiba2/b-r22.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 1, 'في كل صف عدد دوائر الخلية الثالثة يساوي مجموع عددي الخليتين الأوليين: ٢ + ١ = ٣. الإجابة هي الشكل رقم ٢.', '["mawhiba_l2","mawhiba_l2#166"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('237d5c7c-499d-574e-a2c1-388921ee8469', 'spatial', 'انعكاس', 'mawhiba_l2', 'medium', 'image', 'يوضع مرآة عمودية على الحافة اليمنى للشكل الظاهر في الأعلى. أي الأشكال المرقمة يمثل انعكاسه في المرآة؟', '/assets/bunyan/mawhiba2/b-r23.png', '[{"text":"الشكل ١"},{"text":"الشكل ٢"},{"text":"الشكل ٣"},{"text":"الشكل ٤"}]', 0, 'الانعكاس في مرآة عمودية يقلب الشكل يميناً ويساراً مع بقاء الأعلى والأسفل في مكانهما، والناتج هو الشكل رقم ١.', '["mawhiba_l2","mawhiba_l2#167"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('3d5076a7-6e76-5f95-a271-2619f27b01d9', 'quantitative', 'حساب', 'mawhiba_l2', 'medium', 'text', 'قطعة قماش طولها ٣ أمتار قُصّت إلى قطع طول كل منها ٣٥ سم. كم قطعة كاملة نحصل عليها؟', NULL, '[{"text":"٩"},{"text":"٨"},{"text":"١٠"},{"text":"٧"}]', 1, '٣٠٠ ÷ ٣٥ ≈ ٨٫٥٧، فنحصل على ٨ قطع كاملة.', '["mawhiba_l2","mawhiba_l2#168"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('ba58e3d0-86b7-51e8-a8e3-85703ce1f67f', 'scientific', 'بكرات', 'mawhiba_l2', 'medium', 'image', 'يرفع نظام بكرات ثقلاً قدره ٢٠٠ نيوتن، كما في الشكل. عدّ الحبال التي تحمل الكتلة المتحركة، ثم احسب قوة الشدّ اللازمة تقريباً بإهمال الاحتكاك ووزن البكرات.', '/assets/bunyan/mawhiba2/b-s1.png', '[{"text":"٢٠٠ نيوتن"},{"text":"٥٠ نيوتن"},{"text":"١٠٠ نيوتن"},{"text":"٨٠٠ نيوتن"}]', 1, 'في الشكل ٤ حبال زرقاء تحمل الكتلة المتحركة. القوة = الثقل ÷ عدد الحبال الحاملة = ٢٠٠ ÷ ٤ = ٥٠ نيوتن، وطول الحبل المسحوب يزيد ٤ أضعاف.', '["mawhiba_l2","mawhiba_l2#169"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('70195a96-04eb-5d3d-abfd-50e07c82e243', 'scientific', 'تروس', 'mawhiba_l2', 'easy', 'image', 'أربعة تروس متماثلة متعشقة في صف، والترس رقم ١ يدور باتجاه عقارب الساعة (السهم الأحمر). في أي اتجاه يدور الترس رقم ٤؟', '/assets/bunyan/mawhiba2/b-s2.png', '[{"text":"باتجاه عقارب الساعة"},{"text":"لا يدور"},{"text":"يدور باتجاه عقارب الساعة ثم يعكس"},{"text":"عكس عقارب الساعة"}]', 3, 'كل ترس متعشق مع التالي يدور عكسه: ١ مع، ٢ عكس، ٣ مع، ٤ عكس. الترس الرابع يدور عكس عقارب الساعة.', '["mawhiba_l2","mawhiba_l2#170"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('52ed529f-b67d-5be3-ac4d-83fd7857e843', 'scientific', 'كهرباء', 'mawhiba_l2', 'medium', 'text', 'يحدث التيار الكهربائي في سلك عندما:', NULL, '[{"text":"يوضع تحت الشمس"},{"text":"يُلف حول خشب"},{"text":"يُبرّد بالماء"},{"text":"تتحرك الشحنات الكهربائية فيه في مسار مغلق"}]', 3, 'التيار هو حركة الشحنات في دائرة مغلقة.', '["mawhiba_l2","mawhiba_l2#171"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('6a37652d-d36b-5876-a57c-45b01f617c69', 'scientific', 'قوى', 'mawhiba_l2', 'medium', 'text', 'سرعة جسم تتغير من ٠ إلى ٢٠ م/ث خلال ٤ ثوانٍ بانتظام. ما تسارعه؟', NULL, '[{"text":"٢٠ م/ث²"},{"text":"٥ م/ث²"},{"text":"٨٠ م/ث²"},{"text":"٤ م/ث²"}]', 1, 'التسارع = التغير في السرعة ÷ الزمن = ٢٠ ÷ ٤ = ٥ م/ث².', '["mawhiba_l2","mawhiba_l2#172"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('47d2df26-30b8-5f28-a7bd-67db6bfd7ab4', 'scientific', 'أحياء', 'mawhiba_l2', 'medium', 'text', 'في السلسلة الغذائية: عشب ← جرادة ← ضفدع ← ثعبان، ما دور الجرادة؟', NULL, '[{"text":"مستهلك أول"},{"text":"منتج"},{"text":"مفكك"},{"text":"مستهلك ثالث"}]', 0, 'الجرادة تأكل النبات (المنتج) فهي مستهلك أول.', '["mawhiba_l2","mawhiba_l2#173"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('eeb65da5-91ca-53d5-a7d6-5c3629a52db2', 'scientific', 'أحياء', 'mawhiba_l2', 'easy', 'text', 'ما وظيفة كريات الدم الحمراء؟', NULL, '[{"text":"مقاومة الأمراض"},{"text":"نقل الأكسجين"},{"text":"تجلط الدم"},{"text":"هضم الغذاء"}]', 1, 'تحمل الهيموجلوبين الذي ينقل الأكسجين.', '["mawhiba_l2","mawhiba_l2#174"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('07c77ddd-14af-5441-a52d-35365d4f5a10', 'scientific', 'رافعة', 'mawhiba_l2', 'medium', 'image', 'رافعة محمولة على نقطة ارتكاز؛ على اليسار ٣٠ نيوتن على بعد ٢ م، وعلى اليمين ٢٠ نيوتن على بعد ٤ م. أي الجهتين تهبط؟', '/assets/bunyan/mawhiba2/b-s7.png', '[{"text":"اليمنى"},{"text":"اليسرى"},{"text":"تتزن"},{"text":"لا يمكن تحديد ذلك"}]', 0, 'العزم الأيسر = ٣٠ × ٢ = ٦٠ والأيمن = ٢٠ × ٤ = ٨٠. العزم الأكبر على اليمين فتهبط الجهة اليمنى.', '["mawhiba_l2","mawhiba_l2#175"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('d58827fc-7a7f-5437-a9ad-ac413acecd10', 'scientific', 'رافعة', 'mawhiba_l2', 'medium', 'image', 'لوح متزن على نقطة ارتكاز. ثقل ٤٠ نيوتن على بعد ١ م يسار نقطة الارتكاز. ما الثقل الذي يوازنه على بعد ٤ م يمين نقطة الارتكاز؟', '/assets/bunyan/mawhiba2/b-s8.png', '[{"text":"٤٠ نيوتن"},{"text":"١٦٠ نيوتن"},{"text":"٢٠ نيوتن"},{"text":"١٠ نيوتن"}]', 3, '٤٠ × ١ = ٤٠ ويساوي الثقل المجهول × ٤، فالثقل = ١٠ نيوتن.', '["mawhiba_l2","mawhiba_l2#176"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('ac11ffa3-b410-57e7-a888-f469727f36de', 'scientific', 'ضوء', 'mawhiba_l2', 'easy', 'text', 'عند سقوط شعاع ضوء على مرآة مستوية بزاوية سقوط ٣٠°، تكون زاوية الانعكاس:', NULL, '[{"text":"٦٠°"},{"text":"٣٠°"},{"text":"٩٠°"},{"text":"١٥°"}]', 1, 'قانون الانعكاس: زاوية السقوط = زاوية الانعكاس.', '["mawhiba_l2","mawhiba_l2#177"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('4d99d198-dc0e-54ee-af9e-b6b82e3ac1ff', 'scientific', 'كهرباء', 'mawhiba_l2', 'easy', 'text', 'في دائرة كهربائية بسيطة، ماذا يحدث للمصباح إذا فُتح المفتاح؟', NULL, '[{"text":"يزداد لمعانه"},{"text":"يبقى مضيئاً دائماً"},{"text":"ينطفئ لأن الدائرة تُفتح"},{"text":"يتحول إلى بطارية"}]', 2, 'الدائرة المفتوحة لا يسري فيها التيار.', '["mawhiba_l2","mawhiba_l2#178"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('15dba786-58cc-5f18-a2b4-bd37c2968f14', 'scientific', 'قوى', 'mawhiba_l2', 'medium', 'text', 'لماذا يغوص مسمار حاد في الخشب أسهل من مسمار مفلطح بنفس القوة؟', NULL, '[{"text":"لأن وزن الحاد أكبر"},{"text":"لأن الحاد أخف"},{"text":"لأن الضغط أكبر عند المساحة الأصغر"},{"text":"لأن الخشب يلين من الحرارة"}]', 2, 'الضغط = القوة ÷ المساحة، والمساحة الأصغر تعطي ضغطاً أكبر.', '["mawhiba_l2","mawhiba_l2#179"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('00959954-2de9-5759-acad-e8c71efb405e', 'scientific', 'طاقة', 'mawhiba_l2', 'medium', 'text', 'رُفع جسم وزنه ٥٠ نيوتن مسافة ٣ أمتار رأسياً. كم الشغل المبذول؟', NULL, '[{"text":"٥٠ جول"},{"text":"٣ جول"},{"text":"١٥٠ جول"},{"text":"١٦٫٧ جول"}]', 2, 'الشغل = القوة × المسافة = ٥٠ × ٣ = ١٥٠ جول.', '["mawhiba_l2","mawhiba_l2#180"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('451c5c6b-a324-55f1-a093-f41d8b271418', 'scientific', 'منهج', 'mawhiba_l2', 'medium', 'text', 'يبيّن جدول أن النبات الذي أخذ ٤ ساعات ضوء نما ٨ سم، وأخذ ٦ ساعات ضوء نما ١٢ سم، وأخذ ٨ ساعات ضوء نما ١٦ سم. أي علاقة صحيحة؟', NULL, '[{"text":"كلما زاد الضوء قل النمو"},{"text":"لا علاقة بين الضوء والنمو"},{"text":"النمو يتوقف عند ٦ ساعات"},{"text":"كلما زادت ساعات الضوء زاد النمو بشكل طردي"}]', 3, 'النمو ٢ سم لكل ساعة ضوء، علاقة طردية منتظمة.', '["mawhiba_l2","mawhiba_l2#181"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('c9eeea9f-f26f-52ce-a422-821a2e9e6a77', 'scientific', 'صوت', 'mawhiba_l2', 'medium', 'text', 'ما الذي يتغير عندما تزداد تردد موجة الصوت؟', NULL, '[{"text":"تزداد حدّة الصوت"},{"text":"تقل حدة الصوت"},{"text":"تقل سرعة الصوت في الهواء"},{"text":"يختفي الصوت"}]', 0, 'التردد الأعلى يعني نغمة أحدّ.', '["mawhiba_l2","mawhiba_l2#182"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('e3a0f99f-42ec-5e5f-af4e-43eda7edb7b1', 'scientific', 'منهج', 'mawhiba_l2', 'hard', 'text', 'درجة غليان الماء عند ثلاث تجارب: ٩٩°، ١٠٠°، ٩٩٫٥°. أنسب استنتاج:', NULL, '[{"text":"الماء يتغير كل مرة"},{"text":"يغلي عند ٩٩ دائماً"},{"text":"الاختلاف الصغير طبيعي ضمن خطأ القياس"},{"text":"التجارب خاطئة كلها"}]', 2, 'القيم متقاربة جداً، والفروق الصغيرة تنتج من أخطاء القياس والظروف.', '["mawhiba_l2","mawhiba_l2#183"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('8d630cee-ccb0-5b1c-a691-ea245b9ffc03', 'scientific', 'أحياء', 'mawhiba_l2', 'medium', 'text', 'أي أجزاء الخلية النباتية يميزها عن الخلية الحيوانية؟', NULL, '[{"text":"النواة"},{"text":"الغشاء الخلوي"},{"text":"السيتوبلازم"},{"text":"الجدار الخلوي"}]', 3, 'الجدار الخلوي موجود في الخلية النباتية فقط من هذه الخيارات.', '["mawhiba_l2","mawhiba_l2#184"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('9d17c63e-9942-54fd-a39d-2357ba630871', 'scientific', 'أرض', 'mawhiba_l2', 'hard', 'text', 'ما سبب حدوث الفصول الأربعة؟', NULL, '[{"text":"ميل محور الأرض أثناء دورانها حول الشمس"},{"text":"اقتراب الأرض وابتعادها فقط"},{"text":"تغير حجم الشمس"},{"text":"دوران القمر حول الأرض"}]', 0, 'ميل المحور يغير زاوية سقوط أشعة الشمس وطول النهار.', '["mawhiba_l2","mawhiba_l2#185"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('4572b7a1-3c6b-581c-af35-67bd17eea444', 'scientific', 'أحياء', 'mawhiba_l2', 'easy', 'text', 'أي عملية تحوّل النباتات بها ثاني أكسيد الكربون والماء إلى غذاء؟', NULL, '[{"text":"البناء الضوئي"},{"text":"التنفس الخلوي"},{"text":"النتح"},{"text":"الإخصاب"}]', 0, 'البناء الضوئي يستخدم الضوء وثاني أكسيد الكربون والماء لإنتاج سكر وأكسجين.', '["mawhiba_l2","mawhiba_l2#186"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('76409b3b-c8ae-5d09-ad9b-30cb144cccd3', 'scientific', 'طاقة', 'mawhiba_l2', 'easy', 'text', 'عند تسخين قضيب معدني من أحد طرفيه، ينتقل الدفء إلى الطرف الآخر بطريقة:', NULL, '[{"text":"الحمل"},{"text":"الإشعاع في الفراغ فقط"},{"text":"التبخر"},{"text":"التوصيل"}]', 3, 'انتقال الحرارة عبر المواد الصلبة بالتلامس يسمى توصيلاً.', '["mawhiba_l2","mawhiba_l2#187"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('93d40326-bfe2-54a7-a5df-1d8d440c6734', 'scientific', 'مغناطيس', 'mawhiba_l2', 'easy', 'text', 'قطبان مغناطيسيان متشابهان (شمال مع شمال) عند تقريبهما:', NULL, '[{"text":"يتنافران"},{"text":"يتجاذبان"},{"text":"لا يتأثران"},{"text":"يلتصقان دائماً"}]', 0, 'الأقطاب المتشابهة تتنافر، والمختلفة تتجاذب.', '["mawhiba_l2","mawhiba_l2#188"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('d5b85724-63fd-5580-a527-427e51d2dca8', 'scientific', 'أحياء', 'mawhiba_l2', 'medium', 'text', 'إذا اختفت الحشرات الملقحة من منطقة زراعية، فما الأثر المتوقع؟', NULL, '[{"text":"زيادة الأمطار"},{"text":"زيادة الكثافة السكانية للنباتات"},{"text":"انخفاض إنتاج الثمار"},{"text":"ارتفاع الحرارة فوراً"}]', 2, 'التلقيح ضروري لتكوين الثمار في كثير من النباتات.', '["mawhiba_l2","mawhiba_l2#189"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('ee91d75d-f1fa-52bf-a6a7-f957827b4258', 'scientific', 'طاقة', 'mawhiba_l2', 'easy', 'text', 'أي المواد الآتية أفضل عازل للحرارة؟', NULL, '[{"text":"الصوف"},{"text":"النحاس"},{"text":"الألومنيوم"},{"text":"الحديد"}]', 0, 'الصوف يحبس الهواء، والفلزات موصلات جيدة للحرارة.', '["mawhiba_l2","mawhiba_l2#190"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('2213fce0-7918-51d1-a2e1-2319f54ede2a', 'scientific', 'قوى', 'mawhiba_l2', 'easy', 'text', 'أي من التالي مثال على زيادة الاحتكاك؟', NULL, '[{"text":"دهن المحور بزيت"},{"text":"وضع حبيبات رمل على جليد الطريق"},{"text":"تلميع الأرض بالشمع"},{"text":"استعمال كرات التحميل"}]', 1, 'الرمل يخشّن السطح فيزيد الاحتكاك ويمنع الانزلاق.', '["mawhiba_l2","mawhiba_l2#191"]', 1, 'mawhiba_l2');
INSERT OR IGNORE INTO questions (id, skill_area, sub_skill, age_group, difficulty, question_type, question_text_ar, question_image_url, options, correct_option_index, explanation_ar, tags, is_active, source) VALUES ('3f53f368-83c2-5090-a517-05b556e392bd', 'scientific', 'طاقة', 'mawhiba_l2', 'hard', 'text', 'لماذا يغلي الماء في قمة جبل عالٍ عند درجة حرارة أقل من ١٠٠°م؟', NULL, '[{"text":"لأن الماء أنقى"},{"text":"لأن الضغط الجوي أقل"},{"text":"لأن الجبل أبرد فقط"},{"text":"لأن الكثافة أعلى"}]', 1, 'انخفاض الضغط الجوي يخفض درجة الغليان.', '["mawhiba_l2","mawhiba_l2#192"]', 1, 'mawhiba_l2');
